'use client'

import { CTable, CTableHead, CTableRow, CTableHeaderCell, CTableBody, CTableDataCell } from '@coreui/react'
import { useAuthStore } from '@/lib/store/auth-store'
import Switch from '@/components/ui/Switch'
import Badge from '@/components/ui/Badge'
import { showError, showSuccess } from '@/lib/services/errorToast'

const ROLES = [
  { key: 'admin', label: 'Administrador' },
  { key: 'calidad', label: 'Calidad' },
  { key: 'colaborador', label: 'Colaborador' },
]

const DESCRIPCION: Record<string, string> = {
  admin: 'Vista real. Acceso completo al sistema.',
  calidad: 'Gestiona quejas, documentos, SACP y seguimiento.',
  colaborador: 'Solo ve y procesa sus quejas asignadas.',
}

export default function ModoVistaActiva() {
  const user = useAuthStore((s) => s.user)
  const vistaActiva = useAuthStore((s) => s.vistaActiva)
  const setVistaActiva = useAuthStore((s) => s.setVistaActiva)
  const rolReal = user?.rol ?? 'admin'
  const activo = vistaActiva ?? rolReal

  const activar = async (rol: string, ahoraOn: boolean) => {
    try {
      if (!ahoraOn) {
        await setVistaActiva(null)
        showSuccess('Vista real restaurada')
        return
      }
      const objetivo = rol === rolReal ? null : rol
      await setVistaActiva(objetivo)
      const label = ROLES.find((r) => r.key === rol)?.label ?? rol
      showSuccess(objetivo === null ? `Vista de ${label} restaurada` : `Vista de ${label} activada`)
    } catch (error) {
      showError(error as Error, 'No se pudo cambiar la vista')
    }
  }

  return (
    <div className="space-y-4">
      <p className="text-sm text-gray-600">
        Simulá la interfaz de otro rol sin salir de tu sesión. El acceso a Configuración siempre se mantiene para el
        administrador, por lo que podés revertir la vista en cualquier momento.
      </p>
      <div className="table-responsive">
        <CTable align="middle" hover className="w-full select-text">
          <CTableHead>
            <CTableRow className="">
              <CTableHeaderCell className="px-3 py-2 text-left font-semibold">Rol</CTableHeaderCell>
              <CTableHeaderCell className="px-3 py-2 text-left font-semibold">Descripción</CTableHeaderCell>
              <CTableHeaderCell className="px-3 py-2 text-center font-semibold w-40">Vista activa</CTableHeaderCell>
            </CTableRow>
          </CTableHead>
          <CTableBody>
            {ROLES.map((r) => (
              <CTableRow key={r.key} className="">
                <CTableDataCell className="px-3 py-2">
                  <span className="flex items-center gap-2 font-medium text-gray-900">
                    {r.label}
                    {r.key === rolReal && <Badge variant="blue">Rol real</Badge>}
                  </span>
                </CTableDataCell>
                <CTableDataCell className="px-3 py-2">{DESCRIPCION[r.key]}</CTableDataCell>
                <CTableDataCell className="px-3 py-2 text-center">
                  <Switch label={`Vista de ${r.label}`} checked={activo === r.key} onChange={(on) => activar(r.key, on)} />
                </CTableDataCell>
              </CTableRow>
            ))}
          </CTableBody>
        </CTable>
      </div>
    </div>
  )
}

app/configuracion/components/RolesAcceso:
'use client'

import { CTable, CTableHead, CTableRow, CTableHeaderCell, CTableBody, CTableDataCell, CFormLabel } from '@coreui/react'
import { Loader2 } from '@/components/ui/icons'
import { usePermisos, useActualizarPermiso } from '@/lib/queries/usePermisos'
import type { Permiso } from '@/lib/permisos'
import Switch from '@/components/ui/Switch'
import ErrorState from '@/components/ui/ErrorState'
import { showError, showSuccess } from '@/lib/services/errorToast'

const ROLES = [
  { key: 'admin', label: 'Administrador' },
  { key: 'calidad', label: 'Calidad' },
  { key: 'colaborador', label: 'Colaborador' },
]

const MODULOS = [
  { key: 'dashboard', label: 'Dashboard' },
  { key: 'quejas', label: 'Quejas' },
  { key: 'mis_quejas', label: 'Mis Quejas' },
  { key: 'documentos', label: 'Documentos' },
  { key: 'sacp', label: 'SACP' },
  { key: 'riesgos', label: 'Riesgos' },
  { key: 'auditorias', label: 'Auditorías' },
  { key: 'revision', label: 'Revisión por Dirección' },
  { key: 'procesos', label: 'Procesos' },
  { key: 'usuarios', label: 'Usuarios' },
  { key: 'configuracion', label: 'Configuración' },
  { key: 'reporteria', label: 'Reportería' },
]

export default function RolesAccesos() {
  const { data: permisos = [], isLoading, error, refetch, isFetching } = usePermisos()
  const actualizar = useActualizarPermiso()

  if (error) return <ErrorState error={error} title="No se pudieron cargar los permisos" onRetry={() => void refetch()} retrying={isFetching} />

  if (isLoading) {
    return <div className="flex min-h-[300px] items-center justify-center"><Loader2 className="h-8 w-8 animate-spin text-gray-400" /></div>
  }

  const permisoDe = (rol: string, modulo: string): Permiso =>
    permisos.find((p) => p.rol === rol && p.modulo === modulo) ?? { rol, modulo, leer: false, escribir: false }

  const cambiar = async (rol: string, modulo: string, campo: 'leer' | 'escribir', valor: boolean) => {
    const actual = permisoDe(rol, modulo)
    const nuevo: Permiso = { ...actual, rol, modulo }
    if (campo === 'leer') {
      nuevo.leer = valor
      if (!valor) nuevo.escribir = false
    } else {
      nuevo.escribir = valor
    }
    try {
      await actualizar.mutateAsync(nuevo)
      showSuccess('Permiso actualizado')
    } catch (error) {
      showError(error as Error, 'No se pudo actualizar el permiso')
    }
  }

  return (
    <div className="space-y-4">
      <p className="text-sm text-gray-600">
        Controla qué módulos puede ver y editar cada rol. Los cambios aplican al recargar la sesión.
      </p>
      <div className="table-responsive">
        <CTable align="middle" hover className="w-full select-text">
          <CTableHead>
            <CTableRow className="">
              <CTableHeaderCell className="px-3 py-2 text-left font-semibold">Módulo</CTableHeaderCell>
              {ROLES.map((r) => (
                <CTableHeaderCell key={r.key} className="px-3 py-2 text-center font-semibold">
                  {r.label}
                </CTableHeaderCell>
              ))}
            </CTableRow>
          </CTableHead>
          <CTableBody>
            {MODULOS.map((m) => (
              <CTableRow key={m.key} className="">
                <CTableDataCell className="px-3 py-2 font-medium">{m.label}</CTableDataCell>
                {ROLES.map((r) => {
                  const p = permisoDe(r.key, m.key)
                  const bloqueado = r.key === 'admin' && m.key === 'configuracion'
                  return (
                    <CTableDataCell key={r.key} className="px-3 py-2 text-center">
                      <div className="flex items-center justify-center gap-2">
                        <CFormLabel className="flex flex-col items-center gap-0.5 text-sm cursor-pointer">
                          <Switch
                            label={`Ver ${m.label} como ${r.label}`}
                            checked={p.leer}
                            disabled={bloqueado}
                            onChange={(v) => cambiar(r.key, m.key, 'leer', v)}
                          />
                          Ver
                        </CFormLabel>
                        <CFormLabel className="flex flex-col items-center gap-0.5 text-sm cursor-pointer">
                          <Switch
                            label={`Editar ${m.label} como ${r.label}`}
                            checked={p.escribir}
                            disabled={bloqueado || !p.leer}
                            onChange={(v) => cambiar(r.key, m.key, 'escribir', v)}
                          />
                          Editar
                        </CFormLabel>
                      </div>
                    </CTableDataCell>
                  )
                })}
              </CTableRow>
            ))}
          </CTableBody>
        </CTable>
      </div>
    </div>
  )
}

