'use client'

import { useState } from 'react'
import { useQueryClient } from '@tanstack/react-query'
import { CButton, CFormLabel, CFormSelect } from '@coreui/react'
import ErrorState from '@/components/ui/ErrorState'
import { guardarZonaHoraria, useZonaHoraria, zonaHorariaKey } from '@/lib/queries/useZonaHoraria'
import { DEFAULT_TIME_ZONE, TIME_ZONE_GROUPS } from '@/lib/timeZone'
import { getUserError } from '@/lib/errors/userError'
import { showSuccess } from '@/lib/services/errorToast'

/** Editor administrativo de una sola preferencia. La API valida el rol y
 * devuelve únicamente esta clave, sin abrir el resto de la configuración.
 */
export default function ZonaHorariaEditor() {
  const queryClient = useQueryClient()
  const zonaQuery = useZonaHoraria()
  const [borrador, setBorrador] = useState<string | null>(null)
  const [guardando, setGuardando] = useState(false)
  const [errorGuardar, setErrorGuardar] = useState<string | null>(null)

  if (zonaQuery.error) return <ErrorState error={zonaQuery.error} title="No se pudo cargar la zona horaria" onRetry={() => void zonaQuery.refetch()} retrying={zonaQuery.isFetching} />

  const actual = zonaQuery.data ?? DEFAULT_TIME_ZONE
  const seleccion = borrador ?? actual
  const guardar = async () => {
    setGuardando(true)
    setErrorGuardar(null)
    try {
      const guardada = await guardarZonaHoraria(seleccion)
      queryClient.setQueryData(zonaHorariaKey, guardada)
      setBorrador(null)
      await queryClient.invalidateQueries({ queryKey: ['configuraciones_sistema'] })
      showSuccess('Zona horaria actualizada')
    } catch (error) {
      setErrorGuardar(getUserError(error, 'No se pudo guardar la zona horaria').message)
    } finally {
      setGuardando(false)
    }
  }

  const enLista = TIME_ZONE_GROUPS.some((grupo) => grupo.options.some((opcion) => opcion.value === actual))
  return <section className="mb-4 rounded border bg-body p-4" aria-labelledby="titulo-zona-horaria">
    <h3 id="titulo-zona-horaria" className="fs-5 mb-2">Zona horaria del dashboard</h3>
    <p className="text-body-secondary mb-3">Define el año y los meses de los gráficos, y cómo se muestran las fechas y los plazos del dashboard.</p>
    <div className="d-flex align-items-end gap-3 flex-wrap">
      <div style={{ minWidth: 240, maxWidth: 360, flex: '1 1 240px' }}>
        <CFormLabel htmlFor="zona-horaria-sistema">Región y país</CFormLabel>
        <CFormSelect id="zona-horaria-sistema" value={seleccion} disabled={zonaQuery.isPending || guardando}
          onChange={(evento) => { setBorrador(evento.target.value); setErrorGuardar(null) }}>
          {!enLista && <option value={actual}>Actual: {actual}</option>}
          {TIME_ZONE_GROUPS.map((grupo) => <optgroup key={grupo.label} label={grupo.label}>
            {grupo.options.map((opcion) => <option key={opcion.value} value={opcion.value}>{opcion.label} ({opcion.value})</option>)}
          </optgroup>)}
        </CFormSelect>
      </div>
      <CButton color="primary" type="button" onClick={() => void guardar()}
        disabled={zonaQuery.isPending || guardando || seleccion === actual}>
        {guardando ? 'Guardando…' : 'Guardar zona horaria'}
      </CButton>
    </div>
    {errorGuardar && <p role="alert" className="text-danger mt-3 mb-0">{errorGuardar}</p>}
    <p className="small text-body-secondary mt-3 mb-0">Actual: {actual}. Los plazos se muestran según esta zona; las reglas de SLA guardadas no se modifican.</p>
  </section>
}

app/configuracion/page.tsx:
'use client'

import ErrorState from '@/components/ui/ErrorState'

import { CButton, CFormInput, CFormLabel, CTable, CTableHead, CTableRow, CTableHeaderCell, CTableBody, CTableDataCell , CNav, CNavLink, CFormCheck, CCard, CCardHeader, CCardBody } from '@coreui/react'
import styles from './configuracion.module.css'
import { useState, useEffect, useMemo } from 'react'
import { Plus, Save, Trash2, Loader2, Tag, Clock, Settings as SettingsIcon, Check, X, Link as LinkIcon, ShieldCheck, Layers, Sparkles } from '@/components/ui/icons'
import { useRouter } from 'next/navigation'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { supabase } from '@/lib/supabase'
import { useCatalogos, type CatalogoValor } from '@/lib/queries/useCatalogos'
import { useSLAConfig, slaConfigKey, type SLAConfig } from '@/lib/queries/useQuejas'
import { useFormulariosPublicos, useCrearFormularioPublico, useToggleFormularioPublico, useEliminarFormularioPublico } from '@/lib/queries/useFormulariosPublicos'
import { showError, showSuccess } from '@/lib/services/errorToast'
import { useAuthStore } from '@/lib/store/auth-store'
import { formatDays } from '@/lib/utils/format'
import Badge from '@/components/ui/Badge'
import Select from '@/components/ui/Select'
import Button from '@/components/ui/Button'
import Modal from '@/components/Modal'

// Editores disponibles con la ruta: cambiar de pestaña no descarga otro chunk.
import RolesAccesos from './components/RolesAccesos'
import ModoVistaActiva from './components/ModoVistaActiva'
import AIProvidersManager from '@/components/configuracion/AIProvidersManager'
import ZonaHorariaEditor from './components/ZonaHorariaEditor'

type Tab = 'catalogos' | 'sla' | 'general' | 'formularios' | 'roles' | 'vistas' | 'ia'

interface ConfigGeneral { clave: string; valor: unknown; descripcion: string; categoria: string }

const modulos = ['quejas', 'sacp', 'documentos', 'auditorias', 'riesgos', 'general']

const procesosSLA = ['quejas', 'sacp', 'documentos', 'auditorias', 'riesgos', 'revision_direccion']

const descripciones: Record<Tab, string> = {"catalogos":"Organiza los valores disponibles en los formularios de cada módulo.","sla":"Define los tiempos de alerta y vencimiento de cada proceso.","general":"Administra los parámetros generales del sistema de calidad.","formularios":"Gestiona los enlaces públicos para recibir nuevas quejas.","roles":"Configura los permisos de lectura y edición por rol.","vistas":"Revisa la experiencia disponible para cada rol del sistema.","ia":"Administra proveedores, modelos y asignaciones del asistente."}

const coloresBadge = ['red', 'amber', 'green', 'blue', 'orange', 'purple', 'gray']

const CONFIG_META: Record<string, { label: string; descripcion: string }> = {
  'org.nombre': { label: 'Nombre de la organización', descripcion: 'Nombre que se muestra en el sistema y en los documentos generados.' },
  'org.logo_url': { label: 'Logo institucional', descripcion: 'URL de la imagen del logo que identifica al sistema.' },
  'org.zona_horaria': { label: 'Zona horaria', descripcion: 'Zona horaria para fechas y gráficos del dashboard.' },
  'quejas.folio_prefix': { label: 'Prefijo de folios de quejas', descripcion: 'Prefijo que se antepone al número de folio de cada queja.' },
  'sacp.folio_prefix': { label: 'Prefijo de folios de SACP', descripcion: 'Prefijo que se antepone al número de folio de cada acción SACP.' },
  'drive_folder_id_quejas': { label: 'Carpeta de adjuntos en Google Drive', descripcion: 'ID de la carpeta raíz de Drive donde se guardan los adjuntos de las quejas. Cada queja crea una subcarpeta con su folio.' },
  'ai_providers': { label: 'Proveedores de IA', descripcion: 'Conexiones y API keys del asistente de IA. Se administran en la pestaña IA.' },
  'ai_routing': { label: 'Enrutamiento de IA', descripcion: 'Proveedor y modelo asignados a cada módulo. Se administra en la pestaña IA.' },
  'ai_cache_ttl_minutes': { label: 'Caché de modelos (TTL)', descripcion: 'Duración en minutos de la caché de descubrimiento de modelos de IA.' },
}

const CONFIG_OCULTAS = ['ai_modelos_cache_', 'ai_ultimo_exito_', 'ai_fallos_', 'ai_test_resultado_']

function configValorTexto(clave: string, valor: unknown): string {
  if (valor === null || valor === undefined) return ''
  if (clave === 'ai_providers' && Array.isArray(valor)) {
    const nombres = (valor as Array<{ nombre?: string }>).map((p) => p.nombre).filter(Boolean)
    return nombres.length ? `${nombres.length} proveedor(es): ${nombres.join(', ')}` : 'Sin proveedores'
  }
  if (clave === 'ai_routing' && valor && typeof valor === 'object' && !Array.isArray(valor)) {
    const mods = Object.keys(valor)
    return mods.length ? `${mods.length} módulo(s) enrutados` : 'Sin enrutamiento'
  }
  return typeof valor === 'string' ? valor : JSON.stringify(valor)
}

export default function ConfiguracionPage() {
  const { data: catalogos = [], isLoading: loading, error: catalogosError, refetch: retryCatalogos } = useCatalogos()
  const { data: slas = [], isLoading: slasLoading, error: slasError, refetch: retrySlas } = useSLAConfig()
  const queryClient = useQueryClient()
  const invalidateCatalogos = () => queryClient.invalidateQueries({ queryKey: ['catalogos'] })
  const invalidateSLA = () => queryClient.invalidateQueries({ queryKey: slaConfigKey })
  const [tab, setTab] = useState<Tab>('catalogos')
  const { data: configs = [], isLoading: configsLoading, error: configsError, refetch: loadConfigs } = useQuery({
    queryKey: ['configuraciones_sistema'],
    queryFn: async () => {
      const { data, error } = await supabase.from('configuraciones_sistema').select('*').order('categoria').order('clave')
      if (error) throw error
      return (data ?? []) as ConfigGeneral[]
    },
  })
  const configsGenerales = configs.filter((c) => c.clave !== 'org.zona_horaria' && !CONFIG_OCULTAS.some((p) => c.clave.startsWith(p)))
  const [moduloSel, setModuloSel] = useState(modulos[0])
  const [tipoSeleccionado, setFiltroTipo] = useState('')
  const [editCatalogo, setEditCatalogo] = useState<Partial<CatalogoValor>>({})
  const [editSLA, setEditSLA] = useState<Partial<SLAConfig>>({})
  const [editConfig, setEditConfig] = useState<Partial<Omit<ConfigGeneral, 'valor'> & { valor: string }>>({})
  const [nuevoFormOpen, setNuevoFormOpen] = useState(false)
  const [nuevoFormNombre, setNuevoFormNombre] = useState('')

  const { data: formularios = [], isLoading: formulariosLoading, error: formulariosError, refetch: retryFormularios } = useFormulariosPublicos()
  const crearFormulario = useCrearFormularioPublico()
  const toggleFormulario = useToggleFormularioPublico()
  const eliminarFormulario = useEliminarFormularioPublico()


  const tiposDisponibles = useMemo(() => {
    const tipos = new Set<string>()
    for (const c of catalogos) if (c.modulo === moduloSel && (c.activo === null || c.activo === true)) tipos.add(c.tipo)
    return [...tipos].sort()
  }, [catalogos, moduloSel])
  const filtroTipo = tiposDisponibles.includes(tipoSeleccionado) ? tipoSeleccionado : tiposDisponibles[0] ?? ''



  const catalogosFiltrados = catalogos.filter((c) => c.modulo === moduloSel && c.tipo === filtroTipo)

  const guardarCatalogo = async () => {
    if (!editCatalogo.valor?.trim()) return
    const payload = { modulo: editCatalogo.modulo || moduloSel, tipo: filtroTipo, valor: editCatalogo.valor, color: editCatalogo.color || 'gray', orden: editCatalogo.orden ?? 0, activo: editCatalogo.activo ?? true }
    const { error } = editCatalogo.id
      ? await supabase.from('catalogos').update(payload).eq('id', editCatalogo.id)
      : await supabase.from('catalogos').insert([payload])
    if (error) { showError(error, 'No se pudo guardar el catálogo'); return }
    showSuccess(editCatalogo.id ? 'Catálogo actualizado' : 'Valor agregado al catálogo')
    setEditCatalogo({})
    invalidateCatalogos()
  }

  const eliminarCatalogo = async (id: string) => {
    const { error } = await supabase.from('catalogos').delete().eq('id', id)
    if (error) { showError(error, 'No se pudo eliminar el valor'); return }
    showSuccess('Valor eliminado')
    invalidateCatalogos()
  }

  const guardarSLA = async () => {
    if (!editSLA.proceso?.trim() || !editSLA.prioridad?.trim()) return
    const payload = { proceso: editSLA.proceso, prioridad: editSLA.prioridad, dias_alerta: editSLA.dias_alerta ?? 0, dias_vencimiento: editSLA.dias_vencimiento ?? 0 }
    const { error } = editSLA.id
      ? await supabase.from('sla_config').update(payload).eq('id', editSLA.id)
      : await supabase.from('sla_config').insert([payload])
    if (error) { showError(error, 'No se pudo guardar la configuración SLA'); return }
    showSuccess('Configuración SLA guardada')
    setEditSLA({})
    invalidateSLA()
  }

  const eliminarSLA = async (id: string) => {
    const { error } = await supabase.from('sla_config').delete().eq('id', id)
    if (error) { showError(error, 'No se pudo eliminar la configuración SLA'); return }
    showSuccess('Configuración SLA eliminada')
    invalidateSLA()
  }

  const guardarConfig = async () => {
    if (!editConfig.clave?.trim() || !editConfig.valor?.trim()) return
    const payload = { valor: editConfig.valor, descripcion: editConfig.descripcion || '', categoria: editConfig.categoria || 'general' }
    const { error } = await supabase.from('configuraciones_sistema').update(payload).eq('clave', editConfig.clave)
    if (error) { showError(error, 'No se pudo guardar la configuración'); return }
    showSuccess('Configuración guardada')
    setEditConfig({})
    loadConfigs()
  }

  const tabs: { key: Tab; label: string; icon: typeof Tag }[] = [
    { key: 'catalogos', label: 'Catálogos', icon: Tag },
    { key: 'sla', label: 'SLA y Plazos', icon: Clock },
    { key: 'general', label: 'General', icon: SettingsIcon },
    { key: 'formularios', label: 'Formularios', icon: LinkIcon },
    { key: 'roles', label: 'Roles y Accesos', icon: ShieldCheck },
    { key: 'vistas', label: 'Vistas', icon: Layers },
    { key: 'ia', label: 'IA', icon: Sparkles },
  ]

  const user = useAuthStore((s) => s.user)
  const initialized = useAuthStore((s) => s.initialized)
  const router = useRouter()
  useEffect(() => {
    if (!initialized) return
    if (user?.rol !== 'admin') router.replace('/')
  }, [user, initialized, router])
  if (!initialized || user?.rol !== 'admin') {
    return <div className="flex items-center justify-center h-full"><Loader2 className="h-8 w-8 animate-spin text-gray-400" /></div>
  }

  return (
    <div className={`coreui-module ${styles.page}`}>
      <div className={styles.layout}>
        <CCard className={styles.navigation}>
          <p className={styles.navTitle}>Administración</p>
          <CNav as="nav" variant="pills" aria-label="Secciones de configuración">
            {tabs.map(t => { const Icon = t.icon; return <CNavLink key={t.key} as="button" active={tab === t.key} aria-current={tab === t.key ? 'page' : undefined} onClick={() => setTab(t.key)}><Icon size={20} />{t.label}</CNavLink> })}
          </CNav>
        </CCard>
        <CCard className={styles.content}>
          <CCardHeader className={styles.sectionHeader}>
            <span className={styles.sectionIcon}>{tabs.map(t => { const Icon = t.icon; return t.key === tab ? <Icon key={t.key} size={24} /> : null })}</span>
            <div><h2>{tabs.find(t => t.key === tab)?.label}</h2><p>{descripciones[tab]}</p></div>
          </CCardHeader>
          <CCardBody className={styles.sectionBody}>
        {tab === 'catalogos' && catalogosError ? <ErrorState error={catalogosError} title="No se pudieron cargar los catálogos" onRetry={() => void retryCatalogos()} />
        : tab === 'sla' && slasError ? <ErrorState error={slasError} title="No se pudieron cargar los plazos" onRetry={() => void retrySlas()} />
        : tab === 'general' && configsError ? <ErrorState error={configsError} title="No se pudo cargar la configuración" onRetry={() => void loadConfigs()} />
        : tab === 'formularios' && formulariosError ? <ErrorState error={formulariosError} title="No se pudieron cargar los formularios" onRetry={() => void retryFormularios()} />
        : (tab === 'catalogos' && loading) || (tab === 'sla' && slasLoading) || (tab === 'general' && configsLoading) || (tab === 'formularios' && formulariosLoading) ? (
          <div className="flex min-h-[300px] items-center justify-center"><Loader2 className="h-8 w-8 animate-spin text-gray-400" /></div>
        ) : tab === 'catalogos' ? (
          <div className="space-y-4">
            <div className={styles.filters}>
              <div><CFormLabel htmlFor="catalogo-modulo">Módulo</CFormLabel>
              <Select id="catalogo-modulo" value={moduloSel} onChange={(e) => setModuloSel(e.target.value)}>
                {modulos.map((m) => <option key={m} value={m}>{m}</option>)}
              </Select></div>
              <div><CFormLabel htmlFor="catalogo-tipo">Catálogo</CFormLabel>
              <Select id="catalogo-tipo" value={filtroTipo} onChange={(e) => setFiltroTipo(e.target.value)}>
                {tiposDisponibles.length === 0 && <option value="">Sin tipos</option>}
                {tiposDisponibles.map((t) => <option key={t} value={t}>{t.replace(/_/g, ' ')}</option>)}
              </Select></div>
              <CButton color="primary" onClick={() => setEditCatalogo({ modulo: moduloSel, valor: '', color: 'gray', orden: 0, activo: true })}
                className="inline-flex items-center gap-1 px-3 py-1.5 font-medium transition-colors">
                <Plus className="h-3.5 w-3.5" /> Agregar
              </CButton>
            </div>

            {editCatalogo.valor !== undefined && (
              <div className={styles.editor}>
                <div><CFormLabel htmlFor="catalogo-valor">Valor</CFormLabel><CFormInput id="catalogo-valor" placeholder="Nombre del valor" value={editCatalogo.valor || ''} onChange={(e) => setEditCatalogo({ ...editCatalogo, valor: e.target.value })} /></div>
                <div><CFormLabel htmlFor="catalogo-color">Color</CFormLabel><Select id="catalogo-color" value={editCatalogo.color || 'gray'} onChange={(e) => setEditCatalogo({ ...editCatalogo, color: e.target.value })}>
                  {coloresBadge.map((c) => <option key={c} value={c}>{c}</option>)}
                </Select></div>
                <div><CFormLabel htmlFor="catalogo-orden">Orden</CFormLabel><CFormInput id="catalogo-orden" type="number" value={editCatalogo.orden ?? 0} onChange={(e) => setEditCatalogo({ ...editCatalogo, orden: parseInt(e.target.value) || 0 })} /></div>
                <div className={styles.editorActions}>
                <CFormCheck id="catalogo-activo" label="Activo" checked={editCatalogo.activo ?? true} onChange={(e) => setEditCatalogo({ ...editCatalogo, activo: e.target.checked })} />
                <CButton color="primary" onClick={guardarCatalogo} className="px-3 py-1.5 font-medium"><Save className="inline h-3.5 w-3.5" /> Guardar</CButton>
                <CButton color="secondary" variant="outline" onClick={() => setEditCatalogo({})} className="px-3 py-1.5">Cancelar</CButton>
                </div>
              </div>
            )}

            <div className="table-responsive">
              <CTable align="middle" hover className="w-full select-text">
                <CTableHead>
                  <CTableRow className="">
                    <CTableHeaderCell className="px-3 py-2 text-left font-semibold">Valor</CTableHeaderCell>
                    <CTableHeaderCell className="px-3 py-2 text-left font-semibold">Color</CTableHeaderCell>
                    <CTableHeaderCell className="px-3 py-2 text-left font-semibold w-16">Orden</CTableHeaderCell>
                    <CTableHeaderCell className="px-3 py-2 text-left font-semibold w-20">Activo</CTableHeaderCell>
                    <CTableHeaderCell className="px-3 py-2 text-center font-semibold w-24">Acciones</CTableHeaderCell>
                  </CTableRow>
                </CTableHead>
                <CTableBody>
                  {catalogosFiltrados.length === 0 ? (
                    <CTableRow><CTableDataCell colSpan={5} className="px-3 py-8 text-center">No hay valores en este catálogo</CTableDataCell></CTableRow>
                  ) : catalogosFiltrados.map((c) => (
                    <CTableRow key={c.id} className="">
                      <CTableDataCell className="px-3 py-2">{c.valor}</CTableDataCell>
                      <CTableDataCell className="px-3 py-2"><Badge variant={c.color || 'gray'}>{c.color || 'gray'}</Badge></CTableDataCell>
                      <CTableDataCell className="px-3 py-2">{c.orden}</CTableDataCell>
                      <CTableDataCell className="px-3 py-2">{c.activo ? <Check className="h-4 w-4 text-green-600" /> : <X className="h-4 w-4 text-red-600" />}</CTableDataCell>
                      <CTableDataCell className="px-3 py-2 text-center">
                        <div className="flex items-center justify-center gap-1">
                          <CButton color="primary" onClick={() => setEditCatalogo(c)} className="px-2 py-1 font-medium">Editar</CButton>
                          <CButton color="danger" onClick={() => eliminarCatalogo(c.id)} className="px-2 py-1 font-medium">Eliminar</CButton>
                        </div>
                      </CTableDataCell>
                    </CTableRow>
                  ))}
                </CTableBody>
              </CTable>
            </div>
          </div>
        ) : tab === 'sla' ? (
          <div className="space-y-4">
            <CButton color="primary" onClick={() => setEditSLA({ proceso: '', prioridad: '', dias_alerta: 0, dias_vencimiento: 0 })}
              className="inline-flex items-center gap-1 px-3 py-1.5 font-medium transition-colors">
              <Plus className="h-3.5 w-3.5" /> Nueva configuración SLA
            </CButton>

            {editSLA.proceso !== undefined && (
              <div className={styles.editor}>
                <div><CFormLabel htmlFor="sla-proceso">Proceso</CFormLabel><Select id="sla-proceso" value={editSLA.proceso || ''} onChange={(e) => setEditSLA({ ...editSLA, proceso: e.target.value })}>
                  <option value="" disabled>Seleccionar proceso</option>
                  {procesosSLA.map((p) => <option key={p} value={p}>{p.replace(/_/g, ' ')}</option>)}
                </Select></div>
                <div><CFormLabel htmlFor="sla-prioridad">Prioridad</CFormLabel><CFormInput id="sla-prioridad" placeholder="Ej. Alta" value={editSLA.prioridad || ''} onChange={(e) => setEditSLA({ ...editSLA, prioridad: e.target.value })} /></div>
                <div><CFormLabel htmlFor="sla-alerta">Alerta (días)</CFormLabel><CFormInput id="sla-alerta" type="number" value={editSLA.dias_alerta ?? 0} onChange={(e) => setEditSLA({ ...editSLA, dias_alerta: parseInt(e.target.value) || 0 })} /></div>
                <div><CFormLabel htmlFor="sla-vencimiento">Vencimiento (días)</CFormLabel><CFormInput id="sla-vencimiento" type="number" value={editSLA.dias_vencimiento ?? 0} onChange={(e) => setEditSLA({ ...editSLA, dias_vencimiento: parseInt(e.target.value) || 0 })} /></div>
                <div className={styles.editorActions}>
                <CButton color="primary" onClick={guardarSLA} className="px-3 py-1.5 font-medium"><Save className="inline h-3.5 w-3.5" /> Guardar</CButton>
                <CButton color="secondary" variant="outline" onClick={() => setEditSLA({})} className="px-3 py-1.5">Cancelar</CButton>
                </div>
              </div>
            )}

            <div className="table-responsive">
              <CTable align="middle" hover className="w-full select-text">
                <CTableHead>
                  <CTableRow className="">
                    <CTableHeaderCell className="px-3 py-2 text-left font-semibold">Proceso</CTableHeaderCell>
                    <CTableHeaderCell className="px-3 py-2 text-left font-semibold">Prioridad</CTableHeaderCell>
                    <CTableHeaderCell className="px-3 py-2 text-left font-semibold">Alerta (días)</CTableHeaderCell>
                    <CTableHeaderCell className="px-3 py-2 text-left font-semibold">Vencimiento (días)</CTableHeaderCell>
                    <CTableHeaderCell className="px-3 py-2 text-center font-semibold w-24">Acciones</CTableHeaderCell>
                  </CTableRow>
                </CTableHead>
                <CTableBody>
                  {slas.length === 0 ? (
                    <CTableRow><CTableDataCell colSpan={5} className="px-3 py-8 text-center">No hay configuraciones SLA</CTableDataCell></CTableRow>
                  ) : slas.map((s) => (
                    <CTableRow key={s.id} className="">
                      <CTableDataCell className="px-3 py-2 font-medium">{s.proceso}</CTableDataCell>
                      <CTableDataCell className="px-3 py-2"><Badge variant={(s.prioridad || '').toLowerCase() === 'alta' ? 'red' : (s.prioridad || '').toLowerCase() === 'media' ? 'amber' : 'green'}>{s.prioridad}</Badge></CTableDataCell>
                      <CTableDataCell className="px-3 py-2">{formatDays(s.dias_alerta)}</CTableDataCell>
                      <CTableDataCell className="px-3 py-2 font-semibold">{formatDays(s.dias_vencimiento)}</CTableDataCell>
                      <CTableDataCell className="px-3 py-2 text-center">
                        <CButton color="danger" onClick={() => eliminarSLA(s.id)} className="px-2 py-1 font-medium">Eliminar</CButton>
                      </CTableDataCell>
                    </CTableRow>
                  ))}
                </CTableBody>
              </CTable>
            </div>
          </div>
        ) : tab === 'formularios' ? (
          <div className="space-y-4">
            <div className={styles.toolbar}>
              <p className="text-sm text-gray-600">Enlaces públicos de registro de quejas. Cualquier persona con el enlace puede enviar una queja sin iniciar sesión.</p>
              <CButton color="primary" onClick={() => setNuevoFormOpen(true)}
                className="inline-flex h-[38px] shrink-0 items-center gap-1.5 px-3.5 font-medium transition-colors">
                <Plus className="h-4 w-4" /> Nuevo enlace
              </CButton>
            </div>

            <div className="table-responsive">
              <CTable align="middle" hover className="w-full select-text">
                <CTableHead>
                  <CTableRow className="">
                    <CTableHeaderCell className="px-3 py-2 text-left font-semibold">Nombre</CTableHeaderCell>
                    <CTableHeaderCell className="px-3 py-2 text-left font-semibold">Estado</CTableHeaderCell>
                    <CTableHeaderCell className="px-3 py-2 text-left font-semibold">Creado</CTableHeaderCell>
                    <CTableHeaderCell className="px-3 py-2 text-left font-semibold">URL</CTableHeaderCell>
                    <CTableHeaderCell className="px-3 py-2 text-center font-semibold w-36">Acciones</CTableHeaderCell>
                  </CTableRow>
                </CTableHead>
                <CTableBody>
                  {formularios.length === 0 ? (
                    <CTableRow><CTableDataCell colSpan={5} className="px-3 py-8 text-center">No hay enlaces de formularios</CTableDataCell></CTableRow>
                  ) : formularios.map((f) => {
                    const url = `${typeof window !== 'undefined' ? window.location.origin : ''}/q/${f.token}`
                    return (
                      <CTableRow key={f.id} className="">
                        <CTableDataCell className="px-3 py-2 font-medium">{f.nombre}</CTableDataCell>
                        <CTableDataCell className="px-3 py-2">
                          <Badge variant={f.activo ? 'green' : 'gray'}>{f.activo ? 'Activo' : 'Inactivo'}</Badge>
                        </CTableDataCell>
                        <CTableDataCell className="px-3 py-2">{new Date(f.created_at).toLocaleDateString('es-ES')}</CTableDataCell>
                        <CTableDataCell className="px-3 py-2">
                          <span className="font-mono text-xs text-gray-600 break-all">{url}</span>
                        </CTableDataCell>
                        <CTableDataCell className="px-3 py-2 text-center">
                          <div className="flex items-center justify-center gap-1">
                            <CButton color="primary" onClick={() => {
                              navigator.clipboard?.writeText(url)
                              showSuccess('Enlace copiado')
                            }} className="px-2 py-1 font-medium" title="Copiar URL">
                              <LinkIcon className="h-3.5 w-3.5 inline" /> Copiar
                            </CButton>
                            <CButton color="secondary" variant="outline" onClick={async () => {
                              try { await toggleFormulario.mutateAsync({ id: f.id, activo: !f.activo }); showSuccess(f.activo ? 'Enlace desactivado' : 'Enlace activado') }
                              catch (e) { showError(e as Error, 'No se pudo cambiar el estado') }
                            }} className="px-2 py-1 font-medium">
                              {f.activo ? 'Desactivar' : 'Activar'}
                            </CButton>
                            <CButton color="danger" onClick={async () => {
                              if (!confirm('¿Eliminar este enlace? Las quejas ya enviadas se conservan.')) return
                              try { await eliminarFormulario.mutateAsync(f.id); showSuccess('Enlace eliminado') }
                              catch (e) { showError(e as Error, 'No se pudo eliminar el enlace') }
                            }} className="px-2 py-1 font-medium" title="Eliminar">
                              <Trash2 className="h-3.5 w-3.5 inline" />
                            </CButton>
                          </div>
                        </CTableDataCell>
                      </CTableRow>
                    )
                  })}
                </CTableBody>
              </CTable>
            </div>

            <Modal open={nuevoFormOpen} onClose={() => setNuevoFormOpen(false)} title="Nuevo enlace de formulario" size="sm">
              <div className="space-y-4">
                <div>
                  <CFormLabel className="mb-1 block font-medium">Nombre</CFormLabel>
                  <CFormInput className="w-full px-3 py-2" value={nuevoFormNombre} onChange={(e) => setNuevoFormNombre(e.target.value)} placeholder="Ej: Formulario web quejas 2026" />
                </div>
                <div className="flex justify-end gap-3 pt-2">
                  <Button type="button" variant="secondary" onClick={() => setNuevoFormOpen(false)}>Cancelar</Button>
                  <Button type="button" loading={crearFormulario.isPending} disabled={!nuevoFormNombre.trim()} onClick={async () => {
                    try {
                      const nuevo = await crearFormulario.mutateAsync({ nombre: nuevoFormNombre.trim(), creadoPor: user?.id ?? null })
                      setNuevoFormOpen(false)
                      setNuevoFormNombre('')
                      showSuccess('Enlace creado. Copialo para compartirlo.')
                      if (typeof window !== 'undefined') {
                        const url = `${window.location.origin}/q/${nuevo.token}`
                        navigator.clipboard?.writeText(url)
                      }
                    } catch (e) { showError(e as Error, 'No se pudo crear el enlace') }
                  }}>Crear</Button>
                </div>
              </div>
            </Modal>
          </div>
        ) : tab === 'roles' ? (
          <RolesAccesos />
        ) : tab === 'vistas' ? (
          <ModoVistaActiva />
        ) : tab === 'ia' ? (
          <AIProvidersManager />
        ) : (
          <div className="space-y-4">
            <ZonaHorariaEditor />
            <div className="table-responsive">
              <CTable align="middle" hover className="w-full select-text">
                <CTableHead>
                  <CTableRow className="">
                    <CTableHeaderCell className="px-3 py-2 text-left font-semibold">Configuración</CTableHeaderCell>
                    <CTableHeaderCell className="px-3 py-2 text-left font-semibold">Valor</CTableHeaderCell>
                    <CTableHeaderCell className="px-3 py-2 text-left font-semibold">Descripción</CTableHeaderCell>
                    <CTableHeaderCell className="px-3 py-2 text-center font-semibold w-24">Acción</CTableHeaderCell>
                  </CTableRow>
                </CTableHead>
                <CTableBody>
                  {configsGenerales.length === 0 ? (
                    <CTableRow><CTableDataCell colSpan={4} className="px-3 py-8 text-center">No hay configuraciones del sistema</CTableDataCell></CTableRow>
                  ) : configsGenerales.map((cfg) => (
                    <CTableRow key={cfg.clave} className="">
                      <CTableDataCell className="px-3 py-2">
                        <p className="mb-1 font-medium">{CONFIG_META[cfg.clave]?.label ?? cfg.clave}</p>
                        <p className="m-0 font-mono text-xs text-qms-muted">{cfg.clave}</p>
                      </CTableDataCell>
                      <CTableDataCell className="px-3 py-2 max-w-xs">
                        {editConfig.clave === cfg.clave ? (
                          <div className="flex items-center gap-1">
                            <CFormInput className="px-2 py-1 flex-1" value={editConfig.valor || ''} onChange={(e) => setEditConfig({ ...editConfig, valor: e.target.value })} />
                            <CButton color="primary" onClick={guardarConfig} className="px-2 py-1" title="Guardar"><Save className="h-3.5 w-3.5" /></CButton>
                            <CButton color="secondary" variant="outline" onClick={() => setEditConfig({})} className="px-2 py-1" title="Cancelar">X</CButton>
                          </div>
                        ) : (
                          <span className="block truncate font-mono text-sm" title={configValorTexto(cfg.clave, cfg.valor)}>{configValorTexto(cfg.clave, cfg.valor) || '—'}</span>
                        )}
                      </CTableDataCell>
                      <CTableDataCell className="px-3 py-2">{CONFIG_META[cfg.clave]?.descripcion ?? cfg.descripcion}</CTableDataCell>
                      <CTableDataCell className="px-3 py-2 text-center">
                        <CButton color="primary" onClick={() => setEditConfig({ clave: cfg.clave, valor: typeof cfg.valor === 'string' ? cfg.valor : JSON.stringify(cfg.valor), descripcion: cfg.descripcion, categoria: cfg.categoria })} className="px-2 py-1 font-medium">Editar</CButton>
                      </CTableDataCell>
                    </CTableRow>
                  ))}
                </CTableBody>
              </CTable>
            </div>
          </div>
        )}
          </CCardBody>
        </CCard>
      </div>
    </div>
  )
}

app/documentos/page.tsx:
'use client'

import Input from '@/components/ui/tailwind/Input'
import Label from '@/components/ui/tailwind/Label'

import ErrorState from '@/components/ui/tailwind/ErrorState'


import { useState } from 'react'
import { FileText, BookOpen, History, Loader2 } from 'lucide-react'
import { useQueryClient, useQuery } from '@tanstack/react-query'
import { showError, showSuccess } from '@/lib/services/errorToast'
import { supabase } from '@/lib/supabase'
import { useDocumentos, documentosKey, type Documento } from '@/lib/queries/useDocumentos'
import Pagination from '@/components/ui/tailwind/Pagination'
import { useHeaderAction } from '@/hooks/useHeaderAction'
import { Table, TableHead, TableHeaderCell, TableRow, TableCell } from '@/components/ui/tailwind/Table'
import Badge from '@/components/ui/tailwind/Badge'
import EmptyState from '@/components/ui/tailwind/EmptyState'

import Button from '@/components/ui/tailwind/Button'
import Modal from '@/components/ui/tailwind/Modal'
import DeferredMount from '@/components/ui/DeferredMount'

import NuevoDocumentoModal from './components/NuevoDocumentoModal'

const estadoVariant: Record<string, string> = { Borrador: 'gray', Publicado: 'green', Archivado: 'red', 'En Revisión': 'amber' }

type VistaDocumentos = 'todos' | 'maestra' | 'edicion'

const vistas: { key: VistaDocumentos; label: string; icon: typeof FileText }[] = [
  { key: 'todos', label: 'Todos', icon: FileText },
  { key: 'maestra', label: 'Lista Maestra', icon: BookOpen },
  { key: 'edicion', label: 'Edición Viva', icon: History },
]

async function contarDocumentos(estado: string): Promise<number> {
  const q = supabase.from('documentos').select('*', { count: 'exact', head: true })
  const { count } = estado ? await q.eq('estado', estado) : await q
  return count ?? 0
}

export default function DocumentosPage() {
  const [page, setPage] = useState(0)
  const [tab, setTab] = useState<VistaDocumentos>('todos')
  const { data: pagina, isLoading: loading, isFetching, error, refetch } = useDocumentos(page, tab === 'maestra' ? 'Publicado' : tab === 'edicion' ? 'Borrador' : '')
  const documentos = pagina?.data ?? []
  const queryClient = useQueryClient()
  const invalidateDocumentos = () => queryClient.invalidateQueries({ queryKey: documentosKey })
  const [historialOpen, setHistorialOpen] = useState<Documento | null>(null)
  const [editVersion, setEditVersion] = useState('')
  const [nuevoOpen, setNuevoOpen] = useState(false)

  const { data: countTodos } = useQuery({ queryKey: ['documentos', 'count'] as const, queryFn: () => contarDocumentos('') })
  const { data: countPublicados } = useQuery({ queryKey: ['documentos', 'count', 'Publicado'] as const, queryFn: () => contarDocumentos('Publicado') })
  const { data: countBorradores } = useQuery({ queryKey: ['documentos', 'count', 'Borrador'] as const, queryFn: () => contarDocumentos('Borrador') })
  const conteo: Record<VistaDocumentos, number> = { todos: countTodos ?? 0, maestra: countPublicados ?? 0, edicion: countBorradores ?? 0 }

  const publicados = documentos.filter((d) => d.estado === 'Publicado')
  const borradores = documentos.filter((d) => d.estado === 'Borrador')
  const display = tab === 'maestra' ? publicados : tab === 'edicion' ? borradores : documentos

  const handleSaveVersion = async () => {
    if (!historialOpen || !editVersion) return
    const { error } = await supabase.from('documentos').update({ version_actual: editVersion }).eq('id', historialOpen.id)
    if (error) { showError(error, 'No se pudo guardar la versión'); return }
    showSuccess('Versión actualizada')
    setHistorialOpen(null)
    setEditVersion('')
    invalidateDocumentos()
  }

  useHeaderAction({ label: 'Nuevo', onClick: () => setNuevoOpen(true) })

  return (
    <div className="tw:font-sans tw:text-foreground tw:space-y-6">
      <div role="tablist" aria-label="Vistas de documentos" className="tw:mb-6 tw:inline-flex tw:max-w-full tw:flex-wrap tw:items-center tw:gap-1 tw:rounded-lg tw:border tw:border-border tw:bg-surface tw:p-1 tw:shadow-sm">
        {vistas.map(({ key, label, icon: Icon }) => {
          const active = tab === key
          return (
            <button
              key={key}
              type="button"
              role="tab"
              aria-selected={active}
              onClick={() => { setTab(key); setPage(0) }}
              className={`tw:flex tw:items-center tw:gap-2 tw:px-3 tw:py-1.5 tw:text-base tw:font-medium tw:transition-colors tw:sm:px-6 ${active ? 'tw:bg-primary tw:text-white tw:shadow-sm' : 'tw:text-muted tw:hover:bg-gray-100 tw:hover:text-gray-800'}`}
            >
              <Icon className="tw:h-4 tw:w-4" />
              {label}
              <span className={`tw:rounded-full tw:px-2 tw:py-0.5 tw:text-sm tw:font-semibold tw:leading-none ${active ? 'tw:bg-white/20 tw:text-white' : 'tw:bg-gray-100 tw:text-muted'}`}>{conteo[key]}</span>
            </button>
          )
        })}
      </div>

      {error ? <ErrorState error={error} title="No se pudo cargar el listado" onRetry={() => void refetch()} retrying={isFetching} /> : loading ? (
        <div className="tw:flex tw:min-h-[300px] tw:items-center tw:justify-center"><Loader2 className="tw:h-8 tw:w-8 tw:animate-spin tw:text-gray-400" /></div>
      ) : (
      <Table>
        <TableHead>
          <tr>
            <TableHeaderCell>Código</TableHeaderCell>
            <TableHeaderCell>Título</TableHeaderCell>
            <TableHeaderCell>Versión</TableHeaderCell>
            <TableHeaderCell>Estado</TableHeaderCell>
            <TableHeaderCell>Fecha Publicación</TableHeaderCell>
            <TableHeaderCell>Acciones</TableHeaderCell>
          </tr>
        </TableHead>
        <tbody>
          {display.length === 0 ? <EmptyState message="No hay documentos en esta categoría" /> : (
            display.map((doc) => (
              <TableRow key={doc.id}>
                <TableCell><span className="tw:font-mono tw:text-sm">{doc.codigo_doc}</span></TableCell>
                <TableCell className="tw:font-medium tw:text-foreground">{doc.titulo}</TableCell>
                <TableCell className="tw:text-muted">v{doc.version_actual}</TableCell>
                <TableCell><Badge variant={estadoVariant[doc.estado] || 'gray'}>{doc.estado}</Badge></TableCell>
                <TableCell className="tw:text-muted">{doc.fecha_publicacion ? new Date(doc.fecha_publicacion).toLocaleDateString('es-ES') : '-'}</TableCell>
                <TableCell>
                  <div className="tw:flex tw:gap-2">
                    {doc.estado === 'Borrador' && (
                      <Button size="sm" variant="secondary" onClick={() => setHistorialOpen(doc)}>Editar</Button>
                    )}
                    <Button size="sm" variant="ghost" aria-label="Ver historial del documento" onClick={() => setHistorialOpen(doc)}>
                      <History className="tw:h-3.5 tw:w-3.5" aria-hidden="true" />
                    </Button>
                  </div>
                </TableCell>
              </TableRow>
            ))
          )}
        </tbody>
      </Table>
      )}
      <Pagination page={page} count={pagina?.count ?? 0} busy={isFetching} onChange={setPage} />

      <DeferredMount active={nuevoOpen}>
        <NuevoDocumentoModal open={nuevoOpen} onClose={() => setNuevoOpen(false)} onCreated={() => { invalidateDocumentos() }} />
      </DeferredMount>

      <Modal open={!!historialOpen} onClose={() => setHistorialOpen(null)} title={`Historial - ${historialOpen?.codigo_doc}`} size="sm">
        <div className="tw:space-y-3">
          <p className="tw:text-base tw:text-muted">Versión actual: v{historialOpen?.version_actual}</p>
          <div className="tw:flex tw:items-center tw:gap-4">
            <Label htmlFor="documentos-version-editor" className="tw:sr-only">Nueva versión</Label>
            <Input id="documentos-version-editor"
              className="tw:flex-1 tw:px-4 tw:py-2"
              placeholder="Nueva versión (ej: 2.1)"
              value={editVersion}
              onChange={(e) => setEditVersion(e.target.value)}
            />
            <Button size="sm" onClick={handleSaveVersion}>Guardar</Button>
          </div>
          <div className="tw:rounded-lg tw:border tw:border-gray-200 tw:bg-gray-50 tw:p-4 tw:text-base tw:text-muted">
            Historial de cambios se mostrará aquí
          </div>
        </div>
      </Modal>
    </div>
  )
}

app/global-error.tsx:
'use client'

import { getUserError } from '@/lib/errors/userError'

// Este límite reemplaza el layout raíz: debe funcionar sin proveedores ni CSS cargado.
export default function GlobalError({ error, reset }: { error: Error & { digest?: string }; reset: () => void }) {
  const info = getUserError(error)
  const reference = error.digest && /^[a-zA-Z0-9_-]{1,80}$/.test(error.digest) ? error.digest : null
  return <html lang="es"><body style={{ margin: 0, fontFamily: 'system-ui, sans-serif', background: '#f3f4f7', color: '#212631' }}>
    <main style={{ maxWidth: 560, margin: '10vh auto', padding: 32, background: '#fff', borderRadius: 6 }}>
      <h1 style={{ fontSize: 24 }}>No se pudo mostrar el sistema</h1>
      <div role="alert"><p>{info.message}</p><p>{info.action}</p></div>
      {reference && <p>Referencia: {reference}</p>}
      <button type="button" onClick={reset} style={{ padding: '10px 16px', font: 'inherit', cursor: 'pointer' }}>Intentar de nuevo</button>
    </main>
  </body></html>
}

