'use client'

import { CButton, CFormLabel, CFormInput, CTable, CTableHead, CTableRow, CTableHeaderCell, CTableBody, CTableDataCell, CFormCheck } from '@coreui/react'
import { useState, useEffect } from 'react'
import {
  MessageSquareWarning, ClipboardList, FileCheck2,
  ShieldAlert, ClipboardCheck, SearchCheck, Loader2,
  ChevronRight, ChevronLeft, Check, Printer, X,
  Clock, FileText, Layers, Target,
} from '@/components/ui/icons'
import Modal from '@/components/Modal'
import Select from '@/components/ui/Select'
import Button from '@/components/ui/Button'
import Badge from '@/components/ui/Badge'
import { estadoVariant, estadoSACPVariant, estadoDocumentoVariant, prioridadVariant } from '@/lib/constants/variants'
import { fechaLocalVisible } from '@/lib/constants/quejas'
import { showError } from '@/lib/services/errorToast'
import { supabase } from '@/lib/supabase'
import { CChart } from '@coreui/react-chartjs'
import type { ChartData, ChartOptions, Chart as ChartJs } from 'chart.js'

interface Props {
  open: boolean
  onClose: () => void
  moduloInicial: string | null
}

const modulos = [
  { value: 'quejas', label: 'Quejas', icon: MessageSquareWarning },
  { value: 'sacp', label: 'SACP', icon: ClipboardList },
  { value: 'documentos', label: 'Documentos', icon: FileCheck2 },
  { value: 'riesgos', label: 'Riesgos', icon: ShieldAlert },
  { value: 'auditorias', label: 'Auditorías', icon: ClipboardCheck },
  { value: 'revision_direccion', label: 'Revisión por Dirección', icon: SearchCheck },
]

const tablaPorModulo: Record<string, string> = {
  quejas: 'quejas',
  sacp: 'acciones',
  documentos: 'documentos',
  riesgos: 'riesgos',
  auditorias: 'auditorias',
  revision_direccion: 'reuniones',
}

interface FilaInforme { id: string; estado: string; [key: string]: unknown }

interface CatalogoItem { valor: string; color: string }

const TH = 'px-3 py-2.5 text-left text-xs font-semibold uppercase tracking-wide text-qms-muted whitespace-nowrap bg-gray-50'
const TD = 'px-3 py-2 align-middle'

const ESTADOS_FINALES = new Set(['Resuelto', 'Finalizado', 'Cerrada'])
const ESTADO_HEX: Record<string, string> = {
  'Recibido': '#3e7bfa', 'En Investigación': '#f9b115', 'Pendiente de Revisión GC': '#6f42c1',
  'Resuelto': '#2eb85c', 'Finalizado': '#6c757d', 'No Procede': '#e55353',
  'Abierta': '#3e7bfa', 'En Proceso': '#f9b115', 'En Validación': '#6f42c1', 'Cerrada': '#2eb85c',
  'Borrador': '#f9b115', 'En Revisión': '#3e7bfa', 'Publicado': '#2eb85c', 'Archivado': '#6c757d',
}
const CAT_BAR_COLORS: Record<string, string> = {
  'Queja': '#e55353', 'Sugerencia': '#f9b115', 'Reclamo': '#3e7bfa',
  'Denuncia': '#6f42c1', 'Felicitación': '#2eb85c',
}
const DONUT_FALLBACK = '#5856d6'
const CAT_FALLBACK = ['#3e7bfa', '#2eb85c', '#f9b115', '#e55353', '#6f42c1', '#6c757d']
const PRIORIDAD_HEX: Record<string, string> = {
  'Crítica': '#e55353', 'Alta': '#f9b115', 'Media': '#ffc107', 'Baja': '#3e7bfa',
}
const fechaSerie: Record<string, string> = {
  quejas: 'fecha', sacp: 'fecha_apertura', documentos: 'created_at', riesgos: 'fecha_identificacion',
  auditorias: 'fecha_inicio', revision_direccion: 'fecha_programada',
}
const CARD = 'reporte-tarjeta rounded-[12px] border border-gray-200 bg-white p-4 shadow-[0_1px_3px_rgba(15,23,42,0.05)]'
const CARD_TITLE = 'mb-3 flex items-center gap-2 text-[13px] font-semibold uppercase tracking-wide text-gray-500'

function agruparOtros(items: { clave: string; count: number }[], max = 6) {
  if (items.length <= max) return items
  const top = items.slice(0, max - 1)
  const otros = items.slice(max - 1)
  top.push({ clave: 'Otros', count: otros.reduce((s, x) => s + x.count, 0) })
  return top
}

function serieMensual(filas: FilaInforme[], campo: string | undefined) {
  if (!campo) return { labels: [] as string[], datos: [] as number[] }
  const validos = filas
    .map(r => r[campo])
    .filter((v): v is string => typeof v === 'string' && !!v)
    .map(v => new Date(v))
  if (!validos.length) return { labels: [], datos: [] }
  const inicio = new Date(validos[0].getFullYear(), validos[0].getMonth(), 1)
  const fin = new Date(validos.reduce((a, d) => (d > a ? d : a)).getFullYear(), validos.reduce((a, d) => (d > a ? d : a)).getMonth(), 1)
  const meses: Date[] = []
  for (let d = new Date(inicio); d <= fin; d.setMonth(d.getMonth() + 1)) meses.push(new Date(d))
  if (meses.length > 36) return { labels: [], datos: [] }
  const datos = meses.map(m => validos.filter(d => d.getFullYear() === m.getFullYear() && d.getMonth() === m.getMonth()).length)
  const labels = meses.map(m => m.toLocaleDateString('es-ES', { month: 'short', year: '2-digit' }))
  return { labels, datos }
}

const etiquetaBarras = {
  id: 'etiquetaBarras',
  afterDatasetsDraw(chart: ChartJs<'bar'>) {
    const meta = chart.getDatasetMeta(0)
    const dataset = chart.data.datasets[0]
    const valores = (dataset.data as (number | null)[]).map(v => Number(v) || 0)
    const suma = valores.reduce((a, b) => a + b, 0)
    if (!suma) return
    const horizontal = chart.options?.indexAxis === 'y'
    const items = meta.data as unknown as { x: number; y: number }[]
    const { ctx } = chart
    ctx.save()
    ctx.font = '600 11px Inter, system-ui, sans-serif'
    ctx.fillStyle = 'rgba(60, 66, 80, 0.92)'
    ctx.textBaseline = 'middle'
    items.forEach((el, i) => {
      const v = valores[i]
      if (!v) return
      const etiqueta = `${v} · ${Math.round((v / suma) * 100)}%`
      ctx.textAlign = 'left'
      if (horizontal) {
        ctx.fillText(etiqueta, el.x + 6, el.y)
      } else {
        ctx.textBaseline = 'bottom'
        ctx.fillText(etiqueta, el.x, el.y - 4)
        ctx.textBaseline = 'middle'
      }
    })
    ctx.restore()
  },
}

export default function GeneradorInformeModal(props: Props) {
  if (!props.open) return null
  return <ContenidoInforme key={props.moduloInicial ?? 'nuevo'} {...props} />
}

function ContenidoInforme({ open, onClose, moduloInicial }: Props) {
  const [paso, setPaso] = useState(moduloInicial ? 2 : 1)
  const [modulo, setModulo] = useState(moduloInicial ?? '')
  const [incluir, setIncluir] = useState({ tabla: true, resumen: true, vencidos: false, distribucion: false })
  const [fechaDesde, setFechaDesde] = useState('')
  const [fechaHasta, setFechaHasta] = useState('')
  const [filterEstado, setFilterEstado] = useState('')
  const [filterPrioridad, setFilterPrioridad] = useState('')
  const [filterTipo, setFilterTipo] = useState('')
  const [catalogoEstados, setCatalogoEstados] = useState<CatalogoItem[]>([])
  const [catalogoPrioridades, setCatalogoPrioridades] = useState<CatalogoItem[]>([])
  const [catalogoTipos, setCatalogoTipos] = useState<CatalogoItem[]>([])
  const [resultados, setResultados] = useState<FilaInforme[]>([])
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    if (paso !== 2) return
    const cargarCatalogos = async () => {
      setCatalogoEstados([])
      setCatalogoPrioridades([])
      setCatalogoTipos([])
      const tipoEstadoMap: Record<string, string> = {
        quejas: 'estado_queja', sacp: 'estado_sacp', documentos: 'estado_documento',
        auditorias: 'estado_auditoria', riesgos: '', revision_direccion: '',
      }
      const tipoPrioridadMap: Record<string, string> = { quejas: 'prioridad' }
      const tipoCatMap: Record<string, string> = { sacp: 'tipo_sacp' }

      const promises: PromiseLike<CatalogoItem[]>[] = []
      if (tipoEstadoMap[modulo]) promises.push(
        supabase.from('catalogos').select('valor,color').eq('tipo', tipoEstadoMap[modulo]).eq('modulo', modulo).or('activo.is.null,activo.eq.true').order('orden').then(r => r.data || [])
      )
      if (tipoPrioridadMap[modulo]) promises.push(
        supabase.from('catalogos').select('valor,color').eq('tipo', tipoPrioridadMap[modulo]).eq('modulo', modulo).or('activo.is.null,activo.eq.true').order('orden').then(r => r.data || [])
      )
      if (tipoCatMap[modulo]) promises.push(
        supabase.from('catalogos').select('valor,color').eq('tipo', tipoCatMap[modulo]).eq('modulo', modulo).or('activo.is.null,activo.eq.true').order('orden').then(r => r.data || [])
      )
      const results = await Promise.all(promises)
      let idx = 0
      if (tipoEstadoMap[modulo]) { setCatalogoEstados(results[idx]); idx++ }
      if (tipoPrioridadMap[modulo]) { setCatalogoPrioridades(results[idx]); idx++ }
      if (tipoCatMap[modulo]) { setCatalogoTipos(results[idx]); idx++ }
    }
    cargarCatalogos()
  }, [paso, modulo])

  const generarInforme = async () => {
    const tabla = tablaPorModulo[modulo]
    if (!tabla) return
    setLoading(true)
    try {
      const fechaPorModulo: Record<string, string> = { quejas: 'fecha', sacp: 'fecha_apertura', documentos: 'created_at', riesgos: 'fecha_identificacion', auditorias: 'fecha_inicio', revision_direccion: 'fecha_programada' }
      const filas: FilaInforme[] = []
      const batchSize = 500
      for (let desde = 0; ; desde += batchSize) {
        let query = supabase.from(tabla).select('*', { count: 'exact' })
        if (fechaDesde) query = query.gte(fechaPorModulo[modulo], fechaDesde)
        if (fechaHasta) {
          const siguiente = new Date(fechaHasta + 'T00:00:00Z')
          siguiente.setUTCDate(siguiente.getUTCDate() + 1)
          query = query.lt(fechaPorModulo[modulo], siguiente.toISOString().slice(0, 10))
        }
        if (filterEstado) query = query.eq('estado', filterEstado)
        if (filterPrioridad && modulo === 'quejas') query = query.eq('prioridad', filterPrioridad)
        if (filterTipo) query = query.eq('tipo', filterTipo)
        const { data, error, count } = await query.order('id').range(desde, desde + batchSize - 1)
        if (error) throw error
        if ((count ?? 0) > 5000) throw new Error('El informe supera 5000 registros. Ajustá las fechas o filtros para generarlo.')
        const batch = (data ?? []) as FilaInforme[]
        filas.push(...batch)
        if (batch.length < batchSize || filas.length >= (count ?? Infinity)) break
      }
      setResultados(filas)
      setPaso(3)
    } catch (error) {
      showError(error instanceof Error ? error : new Error(String(error)), 'No se pudo generar el informe')
    } finally { setLoading(false) }
  }

  const columnsPorModulo: Record<string, { key: string; label: string }[]> = {
    quejas: [
      { key: 'folio', label: 'Folio' },
      { key: 'fecha_recepcion_gc', label: 'Fecha de recepción' },
      { key: 'area_afectada', label: 'Área' },
      { key: 'tipo', label: 'Tipo' },
      { key: 'cliente_nombre', label: 'Cliente' },
      { key: 'numero_oficio_resolucion', label: 'N.º de oficio' },
      { key: 'observaciones', label: 'Observaciones' },
      { key: 'prioridad', label: 'Prioridad' },
      { key: 'estado', label: 'Estado' },
      { key: 'fecha', label: 'Fecha' },
    ],
    sacp: [
      { key: 'folio', label: 'Folio' },
      { key: 'tipo', label: 'Tipo' },
      { key: 'descripcion', label: 'Descripción' },
      { key: 'estado', label: 'Estado' },
      { key: 'fecha_limite', label: 'Fecha Límite' },
    ],
    documentos: [
      { key: 'codigo_doc', label: 'Código' },
      { key: 'titulo', label: 'Título' },
      { key: 'version_actual', label: 'Versión' },
      { key: 'estado', label: 'Estado' },
      { key: 'fecha_publicacion', label: 'Fecha Publicación' },
    ],
    riesgos: [
      { key: 'folio', label: 'Folio' },
      { key: 'descripcion', label: 'Descripción' },
      { key: 'impacto', label: 'Impacto' },
      { key: 'probabilidad', label: 'Probabilidad' },
      { key: 'estado', label: 'Estado' },
    ],
    auditorias: [
      { key: 'folio', label: 'Folio' },
      { key: 'tipo', label: 'Tipo' },
      { key: 'proceso_area', label: 'Proceso/Área' },
      { key: 'estado', label: 'Estado' },
      { key: 'fecha_inicio', label: 'Fecha Inicio' },
    ],
    revision_direccion: [
      { key: 'titulo', label: 'Título' },
      { key: 'tipo', label: 'Tipo' },
      { key: 'estado', label: 'Estado' },
      { key: 'fecha_programada', label: 'Fecha' },
    ],
  }

  const campoDistribucion: Record<string, string> = {
    quejas: 'tipo',
    documentos: 'categoria',
    riesgos: 'tipo',
    auditorias: 'tipo',
    sacp: 'tipo',
    revision_direccion: 'tipo',
  }

  const campoVencido: Record<string, string> = {
    quejas: 'fecha_sla',
    sacp: 'fecha_limite',
    documentos: 'fecha_publicacion',
    auditorias: 'fecha_inicio',
    riesgos: 'fecha_identificacion',
    revision_direccion: 'fecha_programada',
  }

  const cellValue = (row: FilaInforme, key: string) => {
    const v = row[key]
    if (v == null || v === '') return '—'
    if (key === 'fecha_recepcion_gc' && typeof v === 'string') return fechaLocalVisible(v)
    if (key === 'descripcion' && typeof v === 'string' && v.length > 60) return v.slice(0, 60) + '…'
    if (key === 'impacto' || key === 'probabilidad') return String(v)
    if (typeof v === 'string' && v.includes('T')) return new Date(v).toLocaleDateString('es-ES')
    return String(v)
  }

  const moduloLabel = modulos.find(m => m.value === modulo)?.label ?? ''
  const total = resultados.length
  const resueltos = resultados.filter(r => ESTADOS_FINALES.has(r.estado)).length
  const pendientes = total - resueltos
  const pctResolucion = total > 0 ? Math.round((resueltos / total) * 100) : 0
  const hoy = new Date()
  const vencidosCount = resultados.filter((r) => {
    const campo = campoVencido[modulo]
    const val = campo ? r[campo] : undefined
    if (!val || ['Cerrada', 'Finalizado', 'No Procede'].includes(r.estado)) return false
    return new Date(String(val)) < hoy
  }).length
  const estadoDatos = Object.entries(
    resultados.reduce((acc: Record<string, number>, r) => {
      acc[r.estado] = (acc[r.estado] || 0) + 1
      return acc
    }, {})
  ).map(([estado, count]) => ({ estado, count, pct: total > 0 ? Math.round((count / total) * 100) : 0 })).sort((a, b) => b.count - a.count)
  const catDatos = Object.entries(
    resultados.reduce((acc: Record<string, number>, r) => {
      const val = String(r[campoDistribucion[modulo]] || 'Sin asignar')
      acc[val] = (acc[val] || 0) + 1
      return acc
    }, {})
  ).map(([cat, count]) => ({ cat, count })).sort((a, b) => b.count - a.count)
  const estadosChart = agruparOtros(estadoDatos.map(d => ({ clave: d.estado, count: d.count })), 6)
  const categoriasChart = agruparOtros(catDatos.map(d => ({ clave: d.cat, count: d.count })), 6)
  const estadoColores = estadosChart.map(d => ESTADO_HEX[d.clave] ?? DONUT_FALLBACK)
  const catColores = categoriasChart.map((d, i) => CAT_BAR_COLORS[d.clave] ?? CAT_FALLBACK[i % CAT_FALLBACK.length])
  const serieMensualData = serieMensual(resultados, fechaSerie[modulo])
  const prioridadDatos = (() => {
    if (modulo !== 'quejas') return []
    return Object.entries(
      resultados.reduce((acc: Record<string, number>, r) => {
        const p = String(r.prioridad || 'Sin prioridad')
        acc[p] = (acc[p] || 0) + 1
        return acc
      }, {})
    ).map(([clave, count]) => ({ clave, count })).sort((a, b) => b.count - a.count).slice(0, 4)
  })()
  const hayPrioridades = prioridadDatos.length >= 2
  const prioColores = prioridadDatos.map(d => PRIORIDAD_HEX[d.clave] ?? '#6c757d')
  const estadoMap = modulo === 'sacp' ? estadoSACPVariant : modulo === 'documentos' ? estadoDocumentoVariant : estadoVariant
  const generadoFecha = new Date().toLocaleDateString('es-ES', { day: 'numeric', month: 'long', year: 'numeric' })
  const generadoHora = new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })

  return (
    <Modal open={open} onClose={onClose} title="Generar Informe" size="xl">
      <div className="informe-content">
        {paso < 3 && (
          <div className="mb-6 flex items-center">
            {[{ n: 1, label: 'Selección' }, { n: 2, label: 'Filtros' }, { n: 3, label: 'Informe' }].map((p) => (
              <div key={p.n} className="flex items-center gap-2.5">
                {p.n > 1 && (
                  <div className={`mx-2 h-[2px] w-9 rounded-full sm:w-14 ${paso > p.n ? 'bg-qms-primary' : 'bg-gray-200'}`} />
                )}
                <div
                  className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-full text-sm font-semibold transition-colors ${
                    paso > p.n
                      ? 'bg-qms-primary text-white'
                      : paso === p.n
                        ? 'bg-qms-primary/10 text-qms-primary ring-2 ring-qms-primary/30'
                        : 'bg-gray-200 text-gray-500'
                  }`}
                >
                  {paso > p.n ? <Check className="h-4 w-4" /> : p.n}
                </div>
                <span className={`text-sm ${paso >= p.n ? 'font-medium text-qms-dark' : 'text-gray-400'}`}>{p.label}</span>
              </div>
            ))}
          </div>
        )}

        {paso === 1 && (
          <div className="space-y-6">
            <div>
              <p className="mb-1 text-base font-semibold text-qms-dark">Selecciona un módulo</p>
              <p className="mb-3 text-sm text-qms-muted">Elegí el área sobre la que querés generar el informe.</p>
              <div className="grid grid-cols-2 gap-3">
                {modulos.map((m) => {
                  const Icon = m.icon
                  const selected = modulo === m.value
                  return (
                    <CButton
                      key={m.value}
                      onClick={() => setModulo(m.value)}
                      className={`flex cursor-pointer items-center gap-3 rounded-card border p-4 text-left transition-all duration-200 ${
                        selected
                          ? 'border-qms-primary bg-qms-primary shadow-sm'
                          : 'border-qms-border bg-qms-surface hover:border-qms-primary/60 hover:bg-gray-50'
                      }`}
                    >
                      <div
                        className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-button ${
                          selected ? 'bg-white/20' : 'bg-soft-blue-bg'
                        }`}
                      >
                        <Icon className={`h-5 w-5 ${selected ? 'text-white' : 'text-qms-primary'}`} />
                      </div>
                      <span className={`flex-1 font-medium ${selected ? 'text-white' : 'text-qms-dark'}`}>{m.label}</span>
                      {selected && (
                        <span className="flex h-5 w-5 items-center justify-center rounded-full bg-white/25 text-xs font-semibold text-white">
                          <Check className="h-3 w-3" />
                        </span>
                      )}
                    </CButton>
                  )
                })}
              </div>
            </div>
            <div>
              <p className="mb-1 text-base font-semibold text-qms-dark">¿Qué incluir en el informe?</p>
              <p className="mb-3 text-sm text-qms-muted">Marcá las secciones que debe contener el documento generado.</p>
              <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
                {[
                  { key: 'tabla', label: 'Tabla de registros' },
                  { key: 'resumen', label: 'Resumen por estado' },
                  { key: 'vencidos', label: 'Registros vencidos / por vencer' },
                  { key: 'distribucion', label: 'Distribución por categoría/tipo' },
                ].map((item) => {
                  const activo = incluir[item.key as keyof typeof incluir]
                  return (
                    <CFormLabel
                      key={item.key}
                      className={`flex cursor-pointer items-center gap-2.5 rounded-card border px-3.5 py-3 text-sm font-medium transition-colors ${
                        activo
                          ? 'border-qms-primary bg-qms-primary/5 text-qms-dark'
                          : 'border-qms-border bg-qms-surface text-qms-muted hover:bg-gray-50'
                      }`}
                    >
                      <CFormCheck type="checkbox"
                        checked={activo}
                        onChange={(e) => setIncluir({ ...incluir, [item.key]: e.target.checked })}
                        className={`rounded border-gray-300 ${activo ? 'accent-qms-primary' : ''}`}
                      />
                      {item.label}
                    </CFormLabel>
                  )
                })}
              </div>
            </div>
            <div className="flex items-center justify-between border-t border-gray-100 pt-4">
              <p className="text-xs text-gray-400 hidden sm:block">Proceso de 3 pasos: selección, filtros y documento final.</p>
              <Button onClick={() => { if (modulo) { setPaso(2); setFilterEstado(''); setFilterPrioridad(''); setFilterTipo('') } }}>
                Siguiente <ChevronRight className="h-4 w-4 inline" />
              </Button>
            </div>
          </div>
        )}

        {paso === 2 && (
          <div className="space-y-5">
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-button bg-soft-blue-bg">
                {(() => {
                  const Icon = modulos.find(m => m.value === modulo)?.icon ?? FileText
                  return <Icon className="h-5 w-5 text-qms-primary" />
                })()}
              </div>
              <div>
                <p className="text-base font-semibold text-qms-dark">
                  Informe de {modulos.find(m => m.value === modulo)?.label}
                </p>
                <p className="text-sm text-qms-muted">Filtrá el alcance del documento (opcional).</p>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <CFormLabel className="mb-1 block font-medium">Desde</CFormLabel>
                <CFormInput
                  type="date"
                  className="w-full px-3 py-2"
                  value={fechaDesde}
                  onChange={(e) => setFechaDesde(e.target.value)}
                />
              </div>
              <div>
                <CFormLabel className="mb-1 block font-medium">Hasta</CFormLabel>
                <CFormInput
                  type="date"
                  className="w-full px-3 py-2"
                  value={fechaHasta}
                  onChange={(e) => setFechaHasta(e.target.value)}
                />
              </div>
            </div>
            {modulo === 'quejas' && catalogoEstados.length > 0 && (
              <div>
                <CFormLabel className="mb-1 block font-medium">Estado</CFormLabel>
                <Select className="w-full" value={filterEstado} onChange={(e) => setFilterEstado(e.target.value)}>
                  <option value="">Todos</option>
                  {catalogoEstados.map((e) => <option key={e.valor} value={e.valor}>{e.valor}</option>)}
                </Select>
              </div>
            )}
            {modulo === 'quejas' && catalogoPrioridades.length > 0 && (
              <div>
                <CFormLabel className="mb-1 block font-medium">Prioridad</CFormLabel>
                <Select className="w-full" value={filterPrioridad} onChange={(e) => setFilterPrioridad(e.target.value)}>
                  <option value="">Todas</option>
                  {catalogoPrioridades.map((p) => <option key={p.valor} value={p.valor}>{p.valor}</option>)}
                </Select>
              </div>
            )}
            {modulo === 'sacp' && catalogoEstados.length > 0 && (
              <div>
                <CFormLabel className="mb-1 block font-medium">Estado</CFormLabel>
                <Select className="w-full" value={filterEstado} onChange={(e) => setFilterEstado(e.target.value)}>
                  <option value="">Todos</option>
                  {catalogoEstados.map((e) => <option key={e.valor} value={e.valor}>{e.valor}</option>)}
                </Select>
              </div>
            )}
            {modulo === 'sacp' && catalogoTipos.length > 0 && (
              <div>
                <CFormLabel className="mb-1 block font-medium">Tipo</CFormLabel>
                <Select className="w-full" value={filterTipo} onChange={(e) => setFilterTipo(e.target.value)}>
                  <option value="">Todos</option>
                  {catalogoTipos.map((t) => <option key={t.valor} value={t.valor}>{t.valor}</option>)}
                </Select>
              </div>
            )}
            {modulo === 'auditorias' && catalogoEstados.length > 0 && (
              <div>
                <CFormLabel className="mb-1 block font-medium">Estado</CFormLabel>
                <Select className="w-full" value={filterEstado} onChange={(e) => setFilterEstado(e.target.value)}>
                  <option value="">Todos</option>
                  {catalogoEstados.map((e) => <option key={e.valor} value={e.valor}>{e.valor}</option>)}
                </Select>
              </div>
            )}
            {modulo === 'documentos' && catalogoEstados.length > 0 && (
              <div>
                <CFormLabel className="mb-1 block font-medium">Estado</CFormLabel>
                <Select className="w-full" value={filterEstado} onChange={(e) => setFilterEstado(e.target.value)}>
                  <option value="">Todos</option>
                  {catalogoEstados.map((e) => <option key={e.valor} value={e.valor}>{e.valor}</option>)}
                </Select>
              </div>
            )}

            <div className="flex items-center justify-between pt-2">
              <Button variant="secondary" onClick={() => setPaso(1)}><ChevronLeft className="h-4 w-4 inline" /> Atrás</Button>
              <Button onClick={generarInforme}>Generar informe <ChevronRight className="h-4 w-4 inline" /></Button>
            </div>
          </div>
        )}

        {paso === 3 && (
          <div>
            {loading ? (
              <div className="flex min-h-[200px] items-center justify-center">
                <Loader2 className="h-8 w-8 animate-spin text-qms-primary" />
              </div>
            ) : (
              <div className="reporte-dash space-y-4">
                <div className="reporte-cabecera flex flex-wrap items-center gap-3 border-b border-gray-100 pb-4">
                  <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-[10px] bg-qms-primary text-lg font-bold text-white">E</div>
                  <div className="min-w-0 flex-1">
                    <h2 className="m-0 text-[1.35rem] font-bold tracking-tight text-qms-dark">Informe de {moduloLabel}</h2>
                    <p className="m-0 text-[13px] text-qms-muted">Ente Costarricense de Acreditación · Sistema de Gestión de Calidad</p>
                  </div>
                  <div className="shrink-0 text-right">
                    <p className="m-0 text-xs text-gray-400">Generado: <span className="font-medium text-gray-600">{generadoFecha} · {generadoHora}</span></p>
                    {fechaDesde && (
                      <p className="m-0 text-xs text-gray-400">
                        Período: <span className="font-medium text-gray-600">{new Date(fechaDesde).toLocaleDateString('es-ES')} — {new Date(fechaHasta).toLocaleDateString('es-ES')}</span>
                      </p>
                    )}
                    <p className="m-0 text-xs text-gray-400">Registros: <span className="font-semibold text-qms-primary">{total}</span></p>
                  </div>
                </div>

                {incluir.resumen && (
                  <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-5">
                    {[
                      { label: 'Total', value: total, accent: '#4257be' },
                      { label: 'Resueltos', value: resueltos, accent: '#2eb85c' },
                      { label: 'Pendientes', value: pendientes, accent: '#f9b115' },
                      { label: '% Resolución', value: `${pctResolucion}%`, accent: '#20c997' },
                      { label: 'Vencidos', value: vencidosCount, accent: '#e55353' },
                    ].map((kpi) => (
                      <div key={kpi.label} className="reporte-kpi rounded-[12px] border border-gray-200 bg-white px-4 py-3.5 shadow-[0_1px_3px_rgba(15,23,42,0.05)]">
                        <p className="m-0 text-[11px] font-medium uppercase tracking-wide text-gray-400">{kpi.label}</p>
                        <p className="m-0 mt-1 text-[1.75rem] font-bold leading-none text-qms-dark">{kpi.value}</p>
                        <div className="mt-1.5 h-1 w-8 rounded-full" style={{ background: kpi.accent }} />
                      </div>
                    ))}
                  </div>
                )}

                {total === 0 ? (
                  <div className={CARD}>
                    <p className="m-0 py-6 text-center text-sm text-gray-400">Sin registros para los filtros seleccionados. Ajustá el rango de fechas o los filtros.</p>
                  </div>
                ) : (
                  (() => {
                    const doughnutData: ChartData<'doughnut'> = {
                      labels: estadosChart.map(d => d.clave),
                      datasets: [{
                        data: estadosChart.map(d => d.count),
                        backgroundColor: estadoColores,
                        borderColor: '#ffffff',
                        borderWidth: 2,
                      }],
                    }
                    const doughnutOptions: ChartOptions<'doughnut'> = {
                      responsive: true,
                      maintainAspectRatio: false,
                      cutout: '72%',
                      animation: { duration: 600, easing: 'easeOutQuart' },
                      plugins: {
                        legend: { display: false },
                        tooltip: {
                          callbacks: {
                            label: (ctx) => ` ${String(ctx.label)}: ${ctx.parsed} (${Math.round((Number(ctx.parsed) / total) * 100)}%)`,
                          },
                        },
                      },
                    }
                    const barEstadosData: ChartData<'bar'> = {
                      labels: estadosChart.map(d => d.clave),
                      datasets: [{
                        data: estadosChart.map(d => d.count),
                        backgroundColor: estadoColores,
                        borderRadius: 5,
                        barThickness: 14,
                      }],
                    }
                    const barEstadosOptions: ChartOptions<'bar'> = {
                      indexAxis: 'y',
                      responsive: true,
                      maintainAspectRatio: false,
                      layout: { padding: { right: 64 } },
                      animation: { duration: 600, easing: 'easeOutQuart' },
                      plugins: { legend: { display: false } },
                      scales: {
                        x: { display: false },
                        y: { grid: { display: false }, border: { display: false }, ticks: { font: { size: 12 }, color: '#343a40' } },
                      },
                    }
                    const barCatData: ChartData<'bar'> = {
                      labels: categoriasChart.map(d => d.clave),
                      datasets: [{
                        data: categoriasChart.map(d => d.count),
                        backgroundColor: catColores,
                        borderRadius: 5,
                        barThickness: 26,
                      }],
                    }
                    const barCatOptions: ChartOptions<'bar'> = {
                      responsive: true,
                      maintainAspectRatio: false,
                      animation: { duration: 600, easing: 'easeOutQuart' },
                      plugins: { legend: { display: false } },
                      scales: {
                        x: { grid: { display: false }, border: { display: false }, ticks: { font: { size: 11 }, color: '#6c757d' } },
                        y: { beginAtZero: true, grid: { color: 'rgba(0,0,0,0.05)' }, border: { display: false }, ticks: { precision: 0, font: { size: 10 }, color: '#6c757d' } },
                      },
                    }
                    const lineData: ChartData<'line'> = {
                      labels: serieMensualData.labels,
                      datasets: [{
                        label: 'Registros',
                        data: serieMensualData.datos,
                        borderColor: '#4257be',
                        backgroundColor: 'rgba(66, 87, 190, 0.12)',
                        fill: true,
                        tension: 0.35,
                        borderWidth: 2.5,
                        pointRadius: 3,
                        pointBackgroundColor: '#4257be',
                        pointBorderColor: '#ffffff',
                        pointBorderWidth: 1.5,
                        pointHoverRadius: 5,
                      }],
                    }
                    const lineOptions: ChartOptions<'line'> = {
                      responsive: true,
                      maintainAspectRatio: false,
                      animation: { duration: 600, easing: 'easeOutQuart' },
                      plugins: {
                        legend: { display: false },
                        tooltip: { callbacks: { label: (ctx) => ` ${ctx.parsed.y} registros` } },
                      },
                      scales: {
                        x: { grid: { display: false }, border: { display: false }, ticks: { font: { size: 10 }, color: '#6c757d' } },
                        y: { beginAtZero: true, grid: { color: 'rgba(0,0,0,0.05)' }, border: { display: false }, ticks: { precision: 0, font: { size: 10 }, color: '#6c757d' } },
                      },
                    }
                    const barPrioData: ChartData<'bar'> = {
                      labels: prioridadDatos.map(d => d.clave),
                      datasets: [{
                        data: prioridadDatos.map(d => d.count),
                        backgroundColor: prioColores,
                        borderRadius: 5,
                        barThickness: 26,
                      }],
                    }
                    const hayDonut = incluir.resumen
                    const hayCat = incluir.distribucion
                    const hayMensual = incluir.resumen && serieMensualData.labels.length > 0
                    return (
                      <>
                        {(hayDonut || incluir.resumen) && (
                          <div className="grid grid-cols-1 gap-4 lg:grid-cols-12">
                            {incluir.resumen && (
                              <div className={`${CARD} lg:col-span-5`}>
                                <p className={CARD_TITLE}><Target className="h-3.5 w-3.5 text-qms-primary" /> Distribución de Estados</p>
                                <div className="flex flex-col items-center gap-4 sm:flex-row sm:gap-6">
                                  <div className="relative h-36 w-36 shrink-0">
                                    <CChart type="doughnut" data={doughnutData} options={doughnutOptions} wrapper={false} />
                                    <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center">
                                      <span className="text-2xl font-bold leading-none text-qms-dark">{total}</span>
                                      <span className="mt-0.5 text-[10px] uppercase tracking-wide text-gray-400">Total</span>
                                    </div>
                                  </div>
                                  <ul className="w-full min-w-0 space-y-1">
                                    {estadosChart.map((d) => (
                                      <li key={d.clave} className="flex items-center justify-between gap-2 text-[13px]">
                                        <span className="flex min-w-0 items-center gap-1.5">
                                          <span className="h-2 w-2 shrink-0 rounded-full" style={{ background: ESTADO_HEX[d.clave] ?? DONUT_FALLBACK }} />
                                          <span className="truncate text-gray-600">{d.clave}</span>
                                        </span>
                                        <span className="shrink-0 font-semibold text-qms-dark">{d.count}</span>
                                      </li>
                                    ))}
                                  </ul>
                                </div>
                              </div>
                            )}
                            {incluir.resumen && (
                              <div className={`${CARD} lg:col-span-7`}>
                                <p className={CARD_TITLE}><Layers className="h-3.5 w-3.5 text-qms-primary" /> Estados por Cantidad</p>
                                <div className="h-56 w-full">
                                  <CChart type="bar" data={barEstadosData} options={barEstadosOptions} plugins={[etiquetaBarras]} wrapper={false} />
                                </div>
                              </div>
                            )}
                          </div>
                        )}
                        <div className="grid grid-cols-1 gap-4 lg:grid-cols-12">
                          {hayCat && (
                            <div className={`${CARD} lg:col-span-6`}>
                              <p className={CARD_TITLE}><ClipboardList className="h-3.5 w-3.5 text-qms-primary" /> {modulo === 'quejas' ? 'Categorías' : 'Tipos'} de Registros</p>
                              <div className="h-52 w-full">
                                <CChart type="bar" data={barCatData} options={barCatOptions} plugins={[etiquetaBarras]} wrapper={false} />
                              </div>
                            </div>
                          )}
                          {hayMensual && (
                            <div className={`${CARD} ${hayCat ? 'lg:col-span-6' : 'lg:col-span-12'}`}>
                              <p className={CARD_TITLE}><Clock className="h-3.5 w-3.5 text-qms-primary" /> Evolución Mensual</p>
                              <div className="h-52 w-full">
                                <CChart type="line" data={lineData} options={lineOptions} wrapper={false} />
                              </div>
                            </div>
                          )}
                        </div>
                        {hayPrioridades && incluir.distribucion && (
                          <div className="grid grid-cols-1 gap-4 lg:grid-cols-12">
                            <div className={`${CARD} lg:col-span-6`}>
                              <p className={CARD_TITLE}><ShieldAlert className="h-3.5 w-3.5 text-qms-primary" /> Prioridades</p>
                              <div className="h-48 w-full">
                                <CChart type="bar" data={barPrioData} options={barCatOptions} plugins={[etiquetaBarras]} wrapper={false} />
                              </div>
                            </div>
                          </div>
                        )}
                      </>
                    )
                  })()
                )}

                {incluir.tabla && (
                  <div className={`${CARD} mt-4`}>
                    <p className={CARD_TITLE}><FileText className="h-3.5 w-3.5 text-qms-primary" /> Detalle de Registros</p>
                    <div className="overflow-x-auto">
                      <CTable align="middle" hover className="w-full select-text mb-0">
                        <CTableHead>
                          <CTableRow>
                            {columnsPorModulo[modulo]?.map((col) => (
                              <CTableHeaderCell key={col.key} className={TH}>
                                {col.label}
                              </CTableHeaderCell>
                            ))}
                          </CTableRow>
                        </CTableHead>
                        <CTableBody>
                          {resultados.length === 0 ? (
                            <CTableRow><CTableDataCell colSpan={columnsPorModulo[modulo]?.length || 1} className="px-3 py-8 text-center">Sin registros</CTableDataCell></CTableRow>
                          ) : (
                            resultados.map((row: FilaInforme) => (
                              <CTableRow key={row.id}>
                                {columnsPorModulo[modulo]?.map((col) => (
                                  <CTableDataCell key={col.key} className={TD}>
                                    {col.key === 'estado' ? (
                                      <Badge variant={estadoMap[cellValue(row, col.key)] ?? 'gray'}>{cellValue(row, col.key)}</Badge>
                                    ) : col.key === 'prioridad' ? (
                                      <Badge variant={prioridadVariant[cellValue(row, col.key)] ?? 'gray'}>{cellValue(row, col.key)}</Badge>
                                    ) : (
                                      <span>{cellValue(row, col.key)}</span>
                                    )}
                                  </CTableDataCell>
                                ))}
                              </CTableRow>
                            ))
                          )}
                        </CTableBody>
                      </CTable>
                    </div>
                  </div>
                )}

                {incluir.vencidos && vencidosCount > 0 && campoVencido[modulo] && (
                  <div className={`${CARD} mt-4`}>
                    <p className={CARD_TITLE}><Clock className="h-3.5 w-3.5 text-[#e55353]" /> Registros Vencidos / Por Vencer</p>
                    <div className="overflow-x-auto">
                      <CTable align="middle" hover className="w-full select-text mb-0">
                        <CTableHead>
                          <CTableRow>
                            {columnsPorModulo[modulo]?.map((col) => (
                              <CTableHeaderCell key={col.key} className={TH}>
                                {col.label}
                              </CTableHeaderCell>
                            ))}
                          </CTableRow>
                        </CTableHead>
                        <CTableBody>
                          {resultados.filter((r: FilaInforme) => {
                            const campo = campoVencido[modulo]
                            const val = campo ? r[campo] : undefined
                            if (!val || ['Cerrada', 'Finalizado', 'No Procede'].includes(r.estado)) return false
                            return new Date(String(val)) < hoy
                          }).map((row: FilaInforme) => (
                            <CTableRow key={row.id}>
                              {columnsPorModulo[modulo]?.map((col) => (
                                <CTableDataCell key={col.key} className={TD}>
                                  {cellValue(row, col.key)}
                                </CTableDataCell>
                              ))}
                            </CTableRow>
                          ))}
                        </CTableBody>
                      </CTable>
                    </div>
                  </div>
                )}

                <div className="flex flex-wrap items-center justify-between gap-3 border-t border-gray-100 pt-4 no-print">
                  <Button variant="secondary" onClick={() => setPaso(2)}><ChevronLeft className="h-4 w-4 inline" /> Atrás</Button>
                  <div className="flex items-center gap-2">
                    <Button variant="secondary" onClick={onClose}><X className="h-4 w-4 inline" /> Cerrar</Button>
                    <Button onClick={() => window.print()}><Printer className="h-4 w-4 inline" /> Imprimir / PDF</Button>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </Modal>
  )
}

