            </Button>
            <Button size="sm" onClick={aplicarForm}>
              <Save className="h-3.5 w-3.5 mr-1" /> {editingProvider?.id && editingProvider?.id !== '' ? 'Guardar Cambios' : 'Crear Proveedor'}
            </Button>
          </div>
        </div>
      </Modal>

      <Modal
        open={testModal.abierto}
        onClose={cerrarTestModal}
        title={`Testear modelos — ${testModal.providerNombre}`}
        size="lg"
      >
        <div className="space-y-4">
          <p className="text-sm text-gray-600">
            Se probarán <strong>{testModal.modelos.length}</strong> modelos con 2 prompts (corto y largo).
            {!testModal.enCurso && !testModal.resultado && ' Presione "Iniciar test" para comenzar.'}
            {testModal.enCurso && ' El test está en curso…'}
            {testModal.resultado && (
              <span className={testModal.resultado.malos > 0 ? 'text-amber-600' : 'text-green-600'}>
                {' '}{testModal.resultado.buenos} buenos, {testModal.resultado.malos} malos de {testModal.resultado.total} probados.
              </span>
            )}
            {testModal.cancelado && ' Test cancelado por el usuario.'}
          </p>

          {testModal.enCurso && (
            <div className="flex items-center gap-2 text-xs text-gray-500">
              <Loader2 className="h-3 w-3 animate-spin text-blue-500" />
              {Object.values(testModal.progreso).filter(v => v !== 'pendiente').length} de {testModal.modelos.length} probados
            </div>
          )}

          <div className="rounded-lg border border-qms-border overflow-hidden max-h-[50vh]">
            <div className="overflow-y-auto monday-scroll max-h-[calc(50vh-8px)]">
              <CTable align="middle" hover className="w-full">
                <CTableHead className="sticky top-0 z-10">
                  <CTableRow className="">
                    <CTableHeaderCell className="px-3 py-2 text-left font-semibold">Modelo</CTableHeaderCell>
                    <CTableHeaderCell className="px-3 py-2 text-center font-semibold w-24">Estado</CTableHeaderCell>
                  </CTableRow>
                </CTableHead>
                <CTableBody>
                  {testModal.modelos.map((modelo) => {
                    const status = testModal.progreso[modelo]
                    return (
                      <CTableRow key={modelo} className="">
                        <CTableDataCell className="px-3 py-1.5 font-mono">{modelo}</CTableDataCell>
                        <CTableDataCell className="px-3 py-1.5 text-center">
                          {status === 'pendiente' && <span className="text-xs text-gray-400">—</span>}
                          {status === 'probando' && (
                            <span className="inline-flex items-center gap-1 text-xs text-blue-600">
                              <Loader2 className="h-3 w-3 animate-spin" /> Probando
                            </span>
                          )}
                          {status === 'ok' && (
                            <span className="inline-flex items-center gap-1 text-xs text-green-600">
                              <CheckCircle className="h-3 w-3" /> OK
                            </span>
                          )}
                          {status === 'fallo' && (
                            <span className="inline-flex items-center gap-1 text-xs text-red-600">
                              <XCircle className="h-3 w-3" /> Fallo
                            </span>
                          )}
                        </CTableDataCell>
                      </CTableRow>
                    )
                  })}
                </CTableBody>
              </CTable>
            </div>
          </div>

          <div className="flex items-center justify-end gap-2 pt-2 border-t border-gray-200">
            {!testModal.enCurso && !testModal.resultado && (
              <Button size="sm" onClick={iniciarTest}>
                <Play className="h-3.5 w-3.5 mr-1" /> Iniciar test
              </Button>
            )}
            {testModal.enCurso && (
              <Button size="sm" variant="secondary" onClick={cancelarTest}>
                <ShieldAlert className="h-3.5 w-3.5 mr-1" /> Cancelar
              </Button>
            )}
            {(testModal.resultado || testModal.cancelado || (!testModal.enCurso && testModal.modelos.length > 0)) && (
              <Button size="sm" variant="secondary" onClick={cerrarTestModal}>
                Cerrar
              </Button>
            )}
          </div>
        </div>
      </Modal>
    </div>
  )
}

components/dashboard/BreakdownChart.tsx:
'use client'

import { useMemo } from 'react'
import type { Plugin } from 'chart.js'
import CChart from './Chart'
import { ChartEmpty, opcionesBarras, uiColors, type ColorSemantico } from './chartKit'
import styles from '@/app/dashboard.module.css'

interface Fila { etiqueta: string; total: number; color?: ColorSemantico | 'purple' }

/** Gráfico CoreUI de cantidades reales. Los valores se dibujan al final de cada
 * barra para leerlos sin hover; el eje horizontal siempre representa registros.
 */
export default function BreakdownChart({ filas, nombre = 'Registros' }: { filas: Fila[]; nombre?: string }) {
  const c = uiColors()
  const filasVisibles = useMemo(() => filas.filter((fila) => fila.total >= 0), [filas])
  const datos = useMemo(() => ({
    labels: filasVisibles.map((fila) => fila.etiqueta),
    datasets: [{ label: nombre, data: filasVisibles.map((fila) => fila.total),
      backgroundColor: filasVisibles.map((fila) => c[fila.color ?? 'primary']),
      borderRadius: 4, maxBarThickness: 24 }],
  }), [filasVisibles, c, nombre])
  const valores: Plugin<'bar'> = useMemo(() => ({
    id: 'dashboardValoresBarra',
    afterDatasetsDraw(chart) {
      const ctx = chart.ctx
      ctx.save()
      ctx.fillStyle = c.body
      ctx.font = '600 14px sans-serif'
      ctx.textBaseline = 'middle'
      chart.getDatasetMeta(0).data.forEach((barra, index) => {
        ctx.fillText(String(filasVisibles[index]?.total ?? 0), barra.x + 7, barra.y)
      })
      ctx.restore()
    },
  }), [c.body, filasVisibles])

  if (!filasVisibles.some((fila) => fila.total > 0)) return <ChartEmpty mensaje="No hay registros para este gráfico." />
  const opciones = opcionesBarras(c, { horizontal: true })
  const altura = Math.max(210, filasVisibles.length * 47 + 48)
  return <div className={styles.breakdownChart} style={{ height: altura }}>
    <CChart type="bar" wrapper={false} customTooltips={false} role="img"
      aria-label={`${nombre}: ${filasVisibles.map((fila) => `${fila.etiqueta} ${fila.total}`).join(', ')}`}
      data={datos} plugins={[valores]} options={{ ...opciones, layout: { padding: { right: 38 } } } as never} />
  </div>
}

