'use client'

import { useMemo } from 'react'
import Link from 'next/link'
import {
  CSpinner,
  CRow,
  CCol,
  CCard,
  CCardHeader,
  CCardBody,
  CTable,
  CTableHead,
  CTableHeaderCell,
  CTableBody,
  CTableRow,
  CTableDataCell,
} from '@coreui/react'
import ErrorState from '@/components/ui/ErrorState'
import Badge from '@/components/ui/Badge'
import CChart from './Chart'
import { ChartEmpty, Panel, contarPor, opcionesBarras, opcionesDonut, opcionesLinea, seriesDelAnio, uiColors } from './chartKit'
import { useRiesgosAnalisis } from '@/lib/queries/useModulosAnalisis'
import styles from '@/app/dashboard.module.css'
import { useDashboardNow } from './useDashboardNow'
import { useZonaHoraria } from '@/lib/queries/useZonaHoraria'
import { DEFAULT_TIME_ZONE } from '@/lib/timeZone'

const SERIEDAD_NIVEL: Record<string, number> = { Crítico: 4, Alto: 3, Medio: 2, Bajo: 1 }

export default function RiesgosTab() {
  const { data: filas, isPending, isFetching, error, refetch } = useRiesgosAnalisis()
  const c = uiColors()
  const ahora = useDashboardNow()
  const zonaQuery = useZonaHoraria()
  const zona = zonaQuery.data ?? DEFAULT_TIME_ZONE

  const colorNivel = useMemo(() => ({ Crítico: c.danger, Alto: c.warning, Medio: c.info, Bajo: c.secondary } as Record<string, string>), [c])

  const porNivel = useMemo(() => {
    const grupos = new Map<string, number>()
    for (const f of filas ?? []) {
      const clave = f.nivel?.trim() || 'Sin nivel'
      grupos.set(clave, (grupos.get(clave) ?? 0) + 1)
    }
    return [...grupos.entries()]
      .map(([etiqueta, total]) => ({ etiqueta, total }))
      .sort((a, b) => (SERIEDAD_NIVEL[b.etiqueta] ?? 0) - (SERIEDAD_NIVEL[a.etiqueta] ?? 0) || b.total - a.total)
  }, [filas])
  const nivelData = useMemo(() => ({
    labels: porNivel.map((n) => n.etiqueta),
    datasets: [{ label: 'Riesgos', data: porNivel.map((n) => n.total), backgroundColor: porNivel.map((n) => colorNivel[n.etiqueta] ?? c.muted), borderRadius: 3, maxBarThickness: 16 }],
  }), [porNivel, colorNivel, c])

  const porEstado = useMemo(() => contarPor(filas ?? [], (f) => f.estado ?? 'Sin estado')
    .sort((a, b) => SeriedadEstado(b.etiqueta) - SeriedadEstado(a.etiqueta)), [filas])
  const totalEstado = useMemo(() => (filas ?? []).length, [filas])
  const coloresEstados = useMemo(() => [c.info, c.primary, c.warning, c.success, c.secondary, c.danger], [c])
  const donutData = useMemo(() => ({
    labels: porEstado.map((e) => e.etiqueta),
    datasets: [{ data: porEstado.map((e) => e.total), backgroundColor: porEstado.map((e, i) => coloresEstados[i % coloresEstados.length]), borderWidth: 0 }],
  }), [porEstado, coloresEstados])
  const esDonut = porEstado.length > 0 && porEstado.length <= 6

  const porCategoria = useMemo(() => contarPor(filas ?? [], (f) => f.categoria ?? f.descripcion).slice(0, 8), [filas])
  const categoriaData = useMemo(() => ({
    labels: porCategoria.map((p) => p.etiqueta),
    datasets: [{ label: 'Riesgos', data: porCategoria.map((p) => p.total), backgroundColor: c.primary, borderRadius: 3, maxBarThickness: 16 }],
  }), [porCategoria, c])

  const identificados = useMemo(() => seriesDelAnio(filas ?? [], (f) => f.fecha_identificacion, ahora, zona), [filas, ahora, zona])
  const serieData = useMemo(() => ({
    labels: identificados.meses,
    datasets: [{ label: 'Identificados', data: identificados.valores, borderColor: c.danger, backgroundColor: c.danger, tension: 0.3, fill: false, pointRadius: 3, borderWidth: 2 }],
  }), [identificados, c])
  const identificadosMes = identificados.valores.at(-1) ?? 0

  const prioritarios = useMemo(() => (filas ?? [])
    .filter((f) => f.estado !== 'Cerrado' && f.estado !== 'Mitigado')
    .map((f) => ({ ...f, severidad: (SERIEDAD_NIVEL[f.nivel ?? ''] ?? 0) }))
    .sort((a, b) => b.severidad - a.severidad || (b.impacto * Math.max(b.probabilidad, 1)) - (a.impacto * Math.max(a.probabilidad, 1)))
    .slice(0, 8), [filas])

  if (error) {
    return <ErrorState error={error} title="No se pudieron cargar los datos del módulo de riesgos" onRetry={() => void refetch()} retrying={isFetching} />
  }
  if (zonaQuery.error) return <ErrorState error={zonaQuery.error} title="No se pudo cargar la zona horaria" onRetry={() => void zonaQuery.refetch()} retrying={zonaQuery.isFetching} />
  if (isPending || !filas || zonaQuery.isPending) {
    return <div role="status" className={styles.empty}><CSpinner color="primary" /></div>
  }

  return (
    <div role="tabpanel">
      <CRow className="g-3 mb-4">
        <CCol xs={12} lg={8}>
          <Panel title={`Riesgos identificados por mes en ${identificados.anio}`}>
            {filas.length ? (
              <div className={styles.chartLarge}>
                <CChart
                  type="line"
                  wrapper={false}
                  customTooltips={false}
                  role="img"
                  aria-label={`Riesgos identificados por mes · ${identificadosMes} este mes`}
                  data={serieData}
                  options={opcionesLinea(c) as never}
                />
              </div>
            ) : (
              <ChartEmpty mensaje="No hay riesgos registrados." />
            )}
          </Panel>
        </CCol>
        <CCol xs={12} lg={4}>
          <Panel title="Estado de tratamiento">
            {porEstado.length === 0 ? (
              <ChartEmpty mensaje="No hay riesgos registrados." />
            ) : esDonut ? (
              <>
                <div className={styles.donut}>
                  <CChart
                    type="doughnut"
                    wrapper={false}
                    customTooltips={false}
                    role="img"
                    aria-label={porEstado.map((e) => `${e.etiqueta}: ${e.total}`).join(', ')}
                    data={donutData}
                    options={opcionesDonut() as never}
                  />
                  <div className={styles.donutTotal}><strong>{totalEstado}</strong><span>Riesgos</span></div>
                </div>
                <div className={styles.legend}>
                  {porEstado.map((e, i) => (
                    <span key={e.etiqueta}><i style={{ background: coloresEstados[i % coloresEstados.length] }} />{e.etiqueta} <strong>{e.total}</strong></span>
                  ))}
                </div>
              </>
            ) : (
              <div className={styles.chartMedium}>
                <CChart
                  type="bar"
                  wrapper={false}
                  customTooltips={false}
                  role="img"
                  aria-label={porEstado.map((e) => `${e.etiqueta}: ${e.total}`).join(', ')}
                  data={{ labels: porEstado.map((e) => e.etiqueta), datasets: [{ data: porEstado.map((e) => e.total), backgroundColor: porEstado.map((_, i) => coloresEstados[i % coloresEstados.length]), borderRadius: 3, maxBarThickness: 16 }] }}
                  options={opcionesBarras(c, { horizontal: true }) as never}
                />
              </div>
            )}
          </Panel>
        </CCol>
      </CRow>

      <CRow className="g-3 mb-4">
        <CCol xs={12} lg={6}>
          <Panel title="Riesgos por nivel">
            {porNivel.length === 0 ? (
              <ChartEmpty mensaje="No hay riesgos registrados." />
            ) : (
              <div className={styles.chartMedium}>
                <CChart
                  type="bar"
                  wrapper={false}
                  customTooltips={false}
                  role="img"
                  aria-label={porNivel.map((n) => `${n.etiqueta}: ${n.total}`).join(', ')}
                  data={nivelData}
                  options={opcionesBarras(c, { horizontal: true }) as never}
                />
              </div>
            )}
          </Panel>
        </CCol>
        <CCol xs={12} lg={6}>
          <Panel title="Riesgos por proceso">
            {porCategoria.length === 0 ? (
              <ChartEmpty mensaje="No hay riesgos registrados." />
            ) : (
              <div className={styles.chartMedium}>
                <CChart
                  type="bar"
                  wrapper={false}
                  customTooltips={false}
                  role="img"
                  aria-label={porCategoria.map((p) => `${p.etiqueta}: ${p.total}`).join(', ')}
                  data={categoriaData}
                  options={opcionesBarras(c, { horizontal: true }) as never}
                />
              </div>
            )}
          </Panel>
        </CCol>
      </CRow>

      <CCard className="mb-4">
        <CCardHeader className="d-flex align-items-center justify-content-between flex-wrap gap-2">
          <h2 className="m-0 fs-5">Riesgos prioritarios</h2>
          <Link href="/riesgos" className="fw-medium text-decoration-none" style={{ fontSize: 14 }}>Ver todos los riesgos</Link>
        </CCardHeader>
        <CCardBody className="p-0">
          <CTable hover responsive className="mb-0 align-middle">
            <CTableHead>
              <CTableRow>{['Folio', 'Riesgo', 'Nivel', 'P × I', 'Estado'].map((label) => <CTableHeaderCell key={label} scope="col">{label}</CTableHeaderCell>)}</CTableRow>
            </CTableHead>
            <CTableBody>
              {prioritarios.length === 0 ? (
                <CTableRow><CTableDataCell colSpan={5}><div className={styles.emptyTable}>No hay riesgos prioritarios pendientes.</div></CTableDataCell></CTableRow>
              ) : prioritarios.map((f) => (
                <CTableRow key={f.id}>
                  <CTableDataCell><Link href="/riesgos" className={styles.folio}>{f.folio ?? '—'}</Link></CTableDataCell>
                  <CTableDataCell>{f.descripcion ? `${f.descripcion.slice(0, 60)}${f.descripcion.length > 60 ? '…' : ''}` : '—'}{f.categoria ? <div className="small text-body-secondary">{f.categoria}</div> : null}</CTableDataCell>
                  <CTableDataCell><Badge variant={nivelVariant(f.nivel)}>{f.nivel ?? 'Sin nivel'}</Badge></CTableDataCell>
                  <CTableDataCell>{f.probabilidad} × {f.impacto}</CTableDataCell>
                  <CTableDataCell><Badge variant={estadoVariantRiesgo(f.estado)}>{f.estado ?? '—'}</Badge></CTableDataCell>
                </CTableRow>
              ))}
            </CTableBody>
          </CTable>
        </CCardBody>
      </CCard>
    </div>
  )
}

function nivelVariant(nivel?: string | null): string {
  switch (nivel) {
    case 'Crítico': return 'red'
    case 'Alto': return 'orange'
    case 'Medio': return 'amber'
    case 'Bajo': return 'gray'
    default: return 'gray'
  }
}

function estadoVariantRiesgo(estado?: string | null): string {
  switch (estado) {
    case 'Mitigado':
    case 'Cerrado':
    case 'Resuelto': return 'green'
    case 'En Proceso':
    case 'En tratamiento':
    case 'Mitigación': return 'amber'
    case 'Activo': return 'blue'
    default: return 'gray'
  }
}

function SeriedadEstado(estado: string): number {
  switch (estado) {
    case 'Activo':
    case 'Abierto': return 4
    case 'En Proceso':
    case 'En tratamiento':
    case 'Mitigación': return 3
    case 'En Validación': return 2
    default: return 0
  }
}

components/dashboard/SacpTab.tsx:
'use client'

import { useMemo } from 'react'
import Link from 'next/link'
import {
  CSpinner,
  CRow,
  CCol,
  CCard,
  CCardHeader,
  CCardBody,
  CTable,
  CTableHead,
  CTableHeaderCell,
  CTableBody,
  CTableRow,
  CTableDataCell,
} from '@coreui/react'
import ErrorState from '@/components/ui/ErrorState'
import Badge from '@/components/ui/Badge'
import CChart from './Chart'
import { ChartEmpty, Panel, PanelMetric, contarPor, opcionesBarras, opcionesDonut, opcionesLinea, seriesDelAnio, uiColors } from './chartKit'
import { useSacpAnalisis } from '@/lib/queries/useModulosAnalisis'
import { estadoSACPVariant, prioridadVariant } from '@/lib/constants/variants'
import styles from '@/app/dashboard.module.css'
import { useDashboardNow } from './useDashboardNow'
import { useZonaHoraria } from '@/lib/queries/useZonaHoraria'
import { DEFAULT_TIME_ZONE, fechaCivilClave } from '@/lib/timeZone'
import { estadoPlazo, formatoFechaPlazo } from './plazos'

const ORDEN_SACP = ['Abierta', 'En Proceso', 'En Validación', 'Cerrada']
const COLOR_SACP: Record<string, string> = { Abierta: 'info', 'En Proceso': 'warning', 'En Validación': 'primary', Cerrada: 'success' }

export default function SacpTab() {
  const { data: filas, isPending, isFetching, error, refetch } = useSacpAnalisis()
  const ahora = useDashboardNow()
  const zonaQuery = useZonaHoraria()
  const zona = zonaQuery.data ?? DEFAULT_TIME_ZONE
  const c = uiColors()

  const colorEstado = useMemo(() => {
    const mapa: Record<string, string> = {}
    for (const e of ORDEN_SACP) mapa[e] = { info: c.info, warning: c.warning, primary: c.primary, success: c.success }[COLOR_SACP[e] as 'info' | 'warning' | 'primary' | 'success']
    mapa.Otros = c.muted
    return mapa
  }, [c])

  const porEstado = useMemo(() => {
    const grupos = new Map<string, number>()
    for (const f of filas ?? []) {
      const clave = f.estado?.trim() || 'Otros'
      grupos.set(clave, (grupos.get(clave) ?? 0) + 1)
    }
    return [...grupos.entries()]
      .map(([etiqueta, total]) => ({ etiqueta, total }))
      .sort((a, b) => ORDEN_SACP.indexOf(a.etiqueta) - ORDEN_SACP.indexOf(b.etiqueta))
  }, [filas])
  const totalEstado = useMemo(() => porEstado.reduce((sum, e) => sum + e.total, 0), [porEstado])
  const donutData = useMemo(() => ({
    labels: porEstado.map((e) => e.etiqueta),
    datasets: [{ data: porEstado.map((e) => e.total), backgroundColor: porEstado.map((e) => colorEstado[e.etiqueta] ?? c.muted), borderWidth: 0 }],
  }), [porEstado, colorEstado, c])

  const creadas = useMemo(() => seriesDelAnio(filas ?? [], (f) => f.fecha_apertura, ahora, zona), [filas, ahora, zona])
  const serieData = useMemo(() => ({
    labels: creadas.meses,
    datasets: [{ label: 'Creadas', data: creadas.valores, borderColor: c.primary, backgroundColor: c.primary, tension: 0.3, fill: false, pointRadius: 3, borderWidth: 2 }],
  }), [creadas, c])
  const creadasMes = creadas.valores.at(-1) ?? 0

  const plazos = useMemo(() => {
    const b = { Vencidas: 0, 'Próximas a vencer': 0, 'A tiempo': 0, Cerradas: 0, 'Sin fecha': 0 }
    for (const f of filas ?? []) {
      if (f.estado === 'Cerrada') { b.Cerradas += 1; continue }
      if (!f.fecha_limite) { b['Sin fecha'] += 1; continue }
      const situacion = estadoPlazo(f.fecha_limite, ahora, zona)
      if (situacion === 'Sin fecha') { b['Sin fecha'] += 1; continue }
      if (situacion === 'Vencido') { b.Vencidas += 1; continue }
      const diaLimite = /^\d{4}-\d{2}-\d{2}$/.test(f.fecha_limite)
        ? f.fecha_limite : fechaCivilClave(f.fecha_limite, zona)
      const dias = (Date.parse(`${diaLimite}T00:00:00Z`) - Date.parse(`${fechaCivilClave(ahora, zona)}T00:00:00Z`)) / 86400000
      if (dias <= 7) b['Próximas a vencer'] += 1
      else b['A tiempo'] += 1
    }
    return b
  }, [filas, ahora, zona])
  const plazosData = useMemo(() => ({
    labels: ['Vencidas', 'Próximas a vencer', 'A tiempo', 'Cerradas', 'Sin fecha'],
    datasets: [{ data: [plazos.Vencidas, plazos['Próximas a vencer'], plazos['A tiempo'], plazos.Cerradas, plazos['Sin fecha']], backgroundColor: [c.danger, c.warning, c.info, c.success, c.secondary], borderRadius: 2, maxBarThickness: 18 }],
  }), [plazos, c])

  const porTipo = useMemo(() => contarPor(filas ?? [], (f) => f.tipo).slice(0, 8), [filas])
  const totalPlazos = plazos.Vencidas + plazos['Próximas a vencer'] + plazos['A tiempo'] + plazos.Cerradas + plazos['Sin fecha']
  const tipoData = useMemo(() => ({
    labels: porTipo.map((t) => t.etiqueta),
    datasets: [{ label: 'Acciones', data: porTipo.map((t) => t.total), backgroundColor: c.primary, borderRadius: 3, maxBarThickness: 16 }],
  }), [porTipo, c])

  const atencion = useMemo(() => (filas ?? [])
    .filter((f) => f.estado !== 'Cerrada' && f.estado !== 'En Validación')
    .map((f) => ({ ...f, _ts: f.fecha_limite ? new Date(f.fecha_limite).getTime() : Number.POSITIVE_INFINITY }))
    .sort((a, b) => a._ts - b._ts)
    .slice(0, 8), [filas])

  if (error) {
    return <ErrorState error={error} title="No se pudieron cargar los datos del módulo SACP" onRetry={() => void refetch()} retrying={isFetching} />
  }
  if (zonaQuery.error) return <ErrorState error={zonaQuery.error} title="No se pudo cargar la zona horaria" onRetry={() => void zonaQuery.refetch()} retrying={zonaQuery.isFetching} />
  if (isPending || !filas || zonaQuery.isPending) {
    return <div role="status" className={styles.empty}><CSpinner color="primary" /></div>
  }

  return (
    <div role="tabpanel">
      <CRow className="g-3 mb-4">
        <CCol xs={12} lg={8}>
          <Panel title={`SACP creadas por mes en ${creadas.anio}`} action={<PanelMetric color="primary" etiqueta="Creadas este mes" valor={creadasMes} />}>
            {filas.length ? (
              <div className={styles.chartLarge}>
                <CChart
                  type="line"
                  wrapper={false}
                  customTooltips={false}
                  role="img"
                  aria-label="Acciones SACP creadas por mes"
                  data={serieData}
                  options={opcionesLinea(c) as never}
                />
              </div>
            ) : (
              <ChartEmpty mensaje="No hay acciones SACP registradas." />
            )}
          </Panel>
        </CCol>
        <CCol xs={12} lg={4}>
          <Panel title="SACP por estado">
            {porEstado.length === 0 ? (
              <ChartEmpty mensaje="No hay acciones SACP registradas." />
            ) : (
              <>
                <div className={styles.donut}>
                  <CChart
                    type="doughnut"
                    wrapper={false}
                    customTooltips={false}
                    role="img"
                    aria-label={porEstado.map((e) => `${e.etiqueta}: ${e.total}`).join(', ')}
                    data={donutData}
                    options={opcionesDonut() as never}
                  />
                  <div className={styles.donutTotal}><strong>{totalEstado}</strong><span>Acciones</span></div>
                </div>
                <div className={styles.legend}>
                  {porEstado.map((e) => (
                    <span key={e.etiqueta}><i style={{ background: colorEstado[e.etiqueta] ?? c.muted }} />{e.etiqueta} <strong>{e.total}</strong></span>
                  ))}
                </div>
              </>
            )}
          </Panel>
        </CCol>
      </CRow>

      <CRow className="g-3 mb-4">
        <CCol xs={12} lg={6}>
          <Panel title="Estado de los plazos" action={
            <div className="d-flex gap-2 flex-wrap">
              <PanelMetric color="success" etiqueta="Cerradas" valor={plazos.Cerradas} />
              <PanelMetric color="warning" etiqueta="Próx. vencer" valor={plazos['Próximas a vencer']} />
              <PanelMetric color="danger" etiqueta="Vencidas" valor={plazos.Vencidas} />
            </div>
          }>
            <p className={styles.chartNote}>Cerrada indica el estado de la acción, no si terminó dentro del plazo.</p>
            {totalPlazos === 0 ? (
              <ChartEmpty mensaje="No hay acciones con fecha límite." />
            ) : (
              <div className={styles.chartMedium}>
                <CChart
                  type="bar"
                  wrapper={false}
                  customTooltips={false}
                  role="img"
                  aria-label={`Plazos · cerradas ${plazos.Cerradas}, a tiempo ${plazos['A tiempo']}, próximas a vencer ${plazos['Próximas a vencer']}, vencidas ${plazos.Vencidas}, sin fecha ${plazos['Sin fecha']}`}
                  data={plazosData}
                  options={opcionesBarras(c, { horizontal: true }) as never}
                />
              </div>
            )}
          </Panel>
        </CCol>
        <CCol xs={12} lg={6}>
          <Panel title="SACP por tipo">
            {porTipo.length === 0 ? (
              <ChartEmpty mensaje="No hay acciones SACP registradas." />
            ) : (
              <div className={styles.chartMedium}>
                <CChart
                  type="bar"
                  wrapper={false}
                  customTooltips={false}
                  role="img"
                  aria-label={porTipo.map((t) => `${t.etiqueta}: ${t.total}`).join(', ')}
                  data={tipoData}
                  options={opcionesBarras(c, { horizontal: true }) as never}
                />
              </div>
            )}
          </Panel>
        </CCol>
      </CRow>

      <CCard className="mb-4">
        <CCardHeader className="d-flex align-items-center justify-content-between flex-wrap gap-2">
          <h2 className="m-0 fs-5">SACP que requieren atención</h2>
          <Link href="/sacp" className="fw-medium text-decoration-none" style={{ fontSize: 14 }}>Ver todas las acciones</Link>
        </CCardHeader>
        <CCardBody className="p-0">
          <CTable hover responsive className="mb-0 align-middle">
            <CTableHead>
              <CTableRow>{['Folio', 'Tipo', 'Estado', 'Prioridad', 'Vencimiento'].map((label) => <CTableHeaderCell key={label} scope="col">{label}</CTableHeaderCell>)}</CTableRow>
            </CTableHead>
            <CTableBody>
              {atencion.length === 0 ? (
                <CTableRow><CTableDataCell colSpan={5}><div className={styles.emptyTable}>No hay acciones pendientes de cierre.</div></CTableDataCell></CTableRow>
              ) : atencion.map((f) => (
                <CTableRow key={f.id}>
                  <CTableDataCell><Link href="/sacp" className={styles.folio}>{f.folio ?? '—'}</Link></CTableDataCell>
                  <CTableDataCell>{f.tipo}{f.descripcion ? <div className="small text-body-secondary">{f.descripcion.slice(0, 48)}{f.descripcion.length > 48 ? '…' : ''}</div> : null}</CTableDataCell>
                  <CTableDataCell><Badge variant={estadoSACPVariant[f.estado] ?? 'gray'}>{f.estado}</Badge></CTableDataCell>
                  <CTableDataCell>{f.prioridad ? <Badge variant={prioridadVariant[f.prioridad] ?? 'gray'}>{f.prioridad}</Badge> : '—'}</CTableDataCell>
                  <CTableDataCell className="text-nowrap">{formatoFechaPlazo(f.fecha_limite, zona)}</CTableDataCell>
                </CTableRow>
              ))}
            </CTableBody>
          </CTable>
        </CCardBody>
      </CCard>
    </div>
  )
}

