'use client'

import { useEffect, useId, useRef, useSyncExternalStore } from 'react'
import { CModal, CModalHeader, CModalTitle, CModalBody, CCloseButton } from '@coreui/react'
import styles from './Modal.module.css'

interface ModalProps {
  open: boolean
  onClose: () => void
  title: string
  size?: 'sm' | 'md' | 'lg' | 'xl'
  width?: number
  hideHeader?: boolean
  contentClassName?: string
  bodyClassName?: string
  headerActions?: React.ReactNode
  children: React.ReactNode
}
// Only the top dialog handles focus and Escape; nested confirmations preserve their parent.
let dialogs: string[] = []
const listeners = new Set<() => void>()
const subscribe = (listener: () => void) => { listeners.add(listener); return () => { listeners.delete(listener) } }
const inactiveSubscription = () => () => {}
const snapshot = () => dialogs
const emptyDialogs: string[] = []
const serverSnapshot = () => emptyDialogs
function syncScrollLock() {
  // CoreUI resets body scrolling when an individual modal closes. Keep the lock
  // while a parent dialog remains open.
  document.body.classList.toggle('modal-open', dialogs.length > 0)
  if (dialogs.length) document.body.style.overflow = 'hidden'
  else document.body.style.removeProperty('overflow')
}
function publish() { syncScrollLock(); for (const listener of listeners) listener() }
export default function Modal({ open, onClose, title, size = 'md', width, hideHeader = false, contentClassName, bodyClassName, headerActions, children }: ModalProps) {
  const id = useId()
  const overlayMouseDown = useRef(false)
  // Un modal cerrado no necesita repintarse al abrir/cerrar otros diálogos.
  const activeDialogs = useSyncExternalStore(open ? subscribe : inactiveSubscription, snapshot, serverSnapshot)
  useEffect(() => {
    if (!open) return
    dialogs = [...dialogs, id]
    publish()
    return () => { dialogs = dialogs.filter(dialog => dialog !== id); publish() }
  }, [open, id])
  const level = Math.max(0, activeDialogs.indexOf(id))
  const top = activeDialogs.at(-1) === id
  // CModal modifica el overflow del body incluso montado con visible=false.
  // No montar instancias cerradas: podrían desbloquear otro modal que siga abierto.
  if (!open) return null
  return <div className={`coreui-scope ${styles.host}`} style={{ '--qms-backdrop-z': 1050 + level * 20 } as React.CSSProperties}>
    <CModal visible={open} backdrop="static" portal={false} alignment="center" scrollable size={size === 'md' ? undefined : size}
      onClose={() => queueMicrotask(syncScrollLock)}
      onMouseDown={(event) => { overlayMouseDown.current = event.target === event.currentTarget }}
      onClick={(event) => {
        // Seleccionar texto y soltar fuera del contenido no debe cerrar el expediente.
        if (top && overlayMouseDown.current && event.target === event.currentTarget) onClose()
        overlayMouseDown.current = false
      }}
      onKeyDown={(event) => {
        if (!top || event.key !== 'Escape' || event.defaultPrevented) return
        // El diálogo superior consume Escape; no llega al menú ni al panel de fondo.
        event.preventDefault()
        event.stopPropagation()
        onClose()
      }}
      keyboard={false} focus={top} transition={false} className={`${styles.content} ${contentClassName ?? ''}`} style={{ display: open ? 'block' : undefined, zIndex: 1055 + level * 20, ...(width ? { '--cui-modal-width': `${width}px` } : {}) } as React.CSSProperties} aria-labelledby={`${id}-title`}>
      {hideHeader ? (
        <>
          <CModalTitle className="visually-hidden" id={`${id}-title`}>{title}</CModalTitle>
          <CCloseButton aria-label="Cerrar" className={styles.closeFloating} onClick={onClose} />
        </>
      ) : (
        <CModalHeader closeButton={false}>
          <CModalTitle id={`${id}-title`}>{title}</CModalTitle>
          {headerActions && <div className="ms-auto d-flex align-items-center gap-2">{headerActions}</div>}
          <CCloseButton aria-label="Cerrar" onClick={onClose} />
        </CModalHeader>
      )}
      <CModalBody className={bodyClassName}>{children}</CModalBody>
    </CModal>
  </div>
}

components/quejas/AdjuntoPreviewModal.ts:
'use client'

import { useEffect, useState } from 'react'
import { FileQuestion, Loader2 } from '@/components/ui/icons'
import Modal from '@/components/Modal'
import type { QuejaAdjunto } from '@/lib/queries/useQuejas'
import { supabase } from '@/lib/supabase'

interface Props {
  adjunto: QuejaAdjunto | null
  onClose: () => void
}

function esDrive(storagePath: string): boolean {
  return !storagePath.includes('/')
}

interface VistaLegacyProps {
  url: string
  mime: string
  nombre: string
}

function VistaLegacy({ url, mime, nombre }: VistaLegacyProps) {
  if (mime.startsWith('image/')) {
    return (
      // eslint-disable-next-line @next/next/no-img-element
      <img src={url} alt={nombre} className="mx-auto max-h-[80vh] max-w-full rounded-lg" />
    )
  }
  if (mime.startsWith('video/')) {
    return <video controls src={url} className="max-h-[80vh] w-full rounded-lg bg-black" />
  }
  if (mime.startsWith('audio/')) {
    return <audio controls src={url} className="w-full" />
  }
  if (mime === 'application/pdf') {
    return <iframe src={url} title={nombre} className="h-[80vh] w-full rounded-b-lg border-0" />
  }
  return (
    <div className="flex flex-col items-center gap-3 p-10 text-center">
      <FileQuestion className="h-12 w-12 text-gray-300" />
      <p className="text-sm font-medium text-gray-700">{nombre}</p>
      <p className="text-xs text-gray-400">Sin vista previa para este formato ({mime}).</p>
    </div>
  )
}

export default function AdjuntoPreviewModal({ adjunto, onClose }: Props) {
  const [legacyUrl, setLegacyUrl] = useState<string | null>(null)
  const [legacyError, setLegacyError] = useState(false)

  const adjuntoId = adjunto?.id ?? null
  const [prevAdjuntoId, setPrevAdjuntoId] = useState<string | null>(null)
  if (adjuntoId !== prevAdjuntoId) {
    setPrevAdjuntoId(adjuntoId)
    setLegacyUrl(null)
    setLegacyError(false)
  }


  useEffect(() => {
    if (!adjunto || esDrive(adjunto.storage_path)) return
    let alive = true
    supabase.storage
      .from('quejas-adjuntos')
      .createSignedUrl(adjunto.storage_path, 3600)
      .then(({ data, error }) => {
        if (!alive) return
        if (error || !data?.signedUrl) setLegacyError(true)
        else setLegacyUrl(data.signedUrl)
      })
      .catch(() => {
        if (alive) setLegacyError(true)
      })
    return () => { alive = false }
  }, [adjunto])

  if (!adjunto) return null

  const drive = esDrive(adjunto.storage_path)

  return (
    <Modal open={!!adjunto} onClose={onClose} title={adjunto.nombre} size="xl">
      <div className="flex min-h-0 flex-1 items-center justify-center bg-qms-hover-bg">
        {drive ? (
          <iframe
            src={`https://drive.google.com/file/d/${adjunto.storage_path}/preview`}
            title={adjunto.nombre}
            className="h-[80vh] w-full border-0"
            allow="autoplay"
          />
        ) : legacyUrl ? (
          <div className="w-full p-3">
            <VistaLegacy url={legacyUrl} mime={adjunto.tipo_mime} nombre={adjunto.nombre} />
          </div>
        ) : legacyError ? (
          <div className="flex flex-col items-center gap-2 p-10 text-center">
            <FileQuestion className="h-12 w-12 text-gray-300" />
            <p className="text-sm text-gray-500">No se pudo generar la vista previa de este archivo.</p>
          </div>
        ) : (
          <Loader2 className="h-8 w-8 animate-spin text-gray-400" />
        )}
      </div>
    </Modal>
  )
}

