'use client'

import { CButton, CListGroup, CListGroupItem } from '@coreui/react'
import { Trash2 } from '@/components/ui/icons'
import Badge from '@/components/ui/Badge'
import { formatBytes } from '@/lib/utils/format'
import type { QuejaAdjunto } from '@/lib/queries/useQuejas'

interface ListaAdjuntosProps {
  adjuntos: QuejaAdjunto[]
  onPreview: (a: QuejaAdjunto) => void
  onDownload: (a: QuejaAdjunto) => void
  puedeEliminar?: (a: QuejaAdjunto) => boolean
  onEliminar?: (a: QuejaAdjunto) => void
}

function tipoLabel(mime: string | null) {
  if (!mime) return 'Archivo'
  if (mime.includes('pdf')) return 'Documento PDF'
  if (mime.includes('image')) return 'Imagen'
  if (mime.includes('word') || mime.includes('msword')) return 'Documento Word'
  if (mime.includes('sheet') || mime.includes('excel')) return 'Hoja de cálculo'
  if (mime.startsWith('text/')) return 'Documento de texto'
  return 'Archivo'
}

export default function ListaAdjuntos({
  adjuntos,
  onPreview,
  onDownload,
  puedeEliminar,
  onEliminar,
}: ListaAdjuntosProps) {
  const cliente = adjuntos.filter((a) => !a.usuario_id)
  const analisis = adjuntos.filter((a) => a.usuario_id)

  const renderGrupo = (lista: QuejaAdjunto[], esAnalisis: boolean, titulo: string) => {
    if (lista.length === 0) return null
    return (
      <div className="mb-3">
        <p className="mb-2 text-xs font-semibold uppercase tracking-wide text-qms-muted">{titulo}</p>
        <CListGroup>
          {lista.map((a) => (
            <CListGroupItem key={a.id} className="d-flex flex-wrap align-items-center gap-3 p-6 transition-colors hover:bg-qms-background">
              <div className="flex-grow-1" style={{ minWidth: 160, flexBasis: '55%' }}>
                <p className="mb-1 text-sm fw-semibold text-qms-dark" style={{ maxWidth: '100%', overflowWrap: 'anywhere' }}>
                  {a.nombre}
                </p>
                <div className="d-flex flex-wrap align-items-center gap-2 text-xs text-body-secondary">
                  <span>{tipoLabel(a.tipo_mime)}</span>
                  <span aria-hidden="true">•</span>
                  <span>{formatBytes(a.tamano)}</span>
                  <span aria-hidden="true">•</span>
                  <span>{new Date(a.created_at).toLocaleDateString('es-ES')}</span>
                  {esAnalisis && <Badge variant="blue">Análisis</Badge>}
                </div>
              </div>
              <div className="d-flex align-items-center gap-1 ms-auto">
                <CButton color="primary" variant="outline" size="sm" type="button" onClick={() => onPreview(a)}>
                  Ver archivo
                </CButton>
                <CButton color="primary" variant="outline" size="sm" type="button" onClick={() => onDownload(a)}>
                  Descargar
                </CButton>
                {onEliminar && puedeEliminar?.(a) && (
                  <CButton color="danger" variant="ghost" type="button" onClick={() => onEliminar(a)} title="Eliminar adjunto" aria-label={`Eliminar ${a.nombre}`}>
                    <Trash2 size={18} />
                  </CButton>
                )}
              </div>
            </CListGroupItem>
          ))}
        </CListGroup>
      </div>
    )
  }

  return (
    <>
      {renderGrupo(cliente, false, 'Evidencias del cliente')}
      {renderGrupo(analisis, true, 'Evidencias de análisis')}
    </>
  )
}

