'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { memo, useEffect, useRef } from 'react'
import { useMobileNavigation } from '@/hooks/useMobileNavigation'
import {
  Gauge, MessageSquare, Inbox, FileText, ListChecks, TriangleAlert,
  ClipboardList, Users, Network, UserRound, ChartPie, Settings,
  ChevronDown, ChevronLeft, ChevronRight, X, type LucideIcon,
} from 'lucide-react'
import Button from '@/components/ui/tailwind/Button'
import { cn } from '@/components/ui/tailwind/cn'
import { useSidebarStore } from '@/lib/store/sidebar-store'
import { useAuthStore } from '@/lib/store/auth-store'
import { tienePermiso, moduloDeRuta } from '@/lib/permisos'
import { useHoverPrefetch } from '@/hooks/useHoverPrefetch'
import { fetchQuejas, quejasKey } from '@/lib/queries/useQuejas'
import { paginaKey } from '@/lib/queries/pagination'
import { fetchDocumentos, documentosKey } from '@/lib/queries/useDocumentos'
import { fetchAcciones, accionesKey } from '@/lib/queries/useSACP'
import { fetchRiesgos, riesgosKey } from '@/lib/queries/useRiesgos'
import { fetchAuditorias, auditoriasKey } from '@/lib/queries/useAuditorias'
import { fetchReuniones, reunionesKey } from '@/lib/queries/useReuniones'
import { fetchProcesos, procesosKey } from '@/lib/queries/useProcesos'
import { fetchUsuariosDirect, usuariosQueryKey } from '@/lib/queries/useUsuarios'
import { fetchDashboard, dashboardKey } from '@/lib/queries/useDashboard'

const sections: { label: string; links: { href: string; label: string; icon: LucideIcon }[] }[] = [
  { label: '', links: [{ href: '/', label: 'Dashboard', icon: Gauge }] },
  {
    label: 'Gestión de calidad',
    links: [
      { href: '/quejas', label: 'Quejas', icon: MessageSquare },
      { href: '/mis-quejas', label: 'Mis Quejas', icon: Inbox },
      { href: '/documentos', label: 'Documentos', icon: FileText },
      { href: '/sacp', label: 'SACP', icon: ListChecks },
    ],
  },
  {
    label: 'Seguimiento',
    links: [
      { href: '/riesgos', label: 'Riesgos', icon: TriangleAlert },
      { href: '/auditorias', label: 'Auditorías', icon: ClipboardList },
      { href: '/revision', label: 'Revisión por Dirección', icon: Users },
      { href: '/procesos', label: 'Procesos', icon: Network },
    ],
  },
  {
    label: 'Administración',
    links: [
      { href: '/usuarios', label: 'Usuarios', icon: UserRound },
      { href: '/reporteria', label: 'Reportería', icon: ChartPie },
      { href: '/configuracion', label: 'Configuración', icon: Settings },
    ],
  },
]

const prefetchMap: Record<string, { queryKey: readonly unknown[]; queryFn: () => PromiseLike<unknown> }> = {
  '/':           { queryKey: dashboardKey, queryFn: fetchDashboard },
  '/quejas':     { queryKey: quejasKey({ page: 0, pageSize: 25 }), queryFn: () => fetchQuejas({ page: 0, pageSize: 25 }) },
  '/documentos': { queryKey: paginaKey(documentosKey), queryFn: () => fetchDocumentos() },
  '/sacp':       { queryKey: paginaKey(accionesKey), queryFn: () => fetchAcciones() },
  '/riesgos':    { queryKey: paginaKey(riesgosKey), queryFn: () => fetchRiesgos() },
  '/auditorias': { queryKey: paginaKey(auditoriasKey), queryFn: () => fetchAuditorias() },
  '/revision':   { queryKey: paginaKey(reunionesKey), queryFn: () => fetchReuniones() },
  '/procesos':   { queryKey: paginaKey(procesosKey), queryFn: () => fetchProcesos() },
  '/usuarios':   { queryKey: usuariosQueryKey(), queryFn: () => fetchUsuariosDirect() },
  '/reporteria': { queryKey: ['reporteria'], queryFn: () => Promise.resolve([]) },
}

function Sidebar() {
  const pathname = usePathname()
  const { collapsed, hidden, toggleCollapsed, mobileOpen, setMobileOpen, expandedGroups, setGroupOpen } = useSidebarStore()
  const user = useAuthStore((s) => s.user)
  const permisos = useAuthStore((s) => s.permisos)
  const prefetch = useHoverPrefetch()
  const mobile = useMobileNavigation()
  const dialog = useRef<HTMLDialogElement>(null)
  const compact = collapsed && !mobile
  const labelClass = compact
    ? 'tw:invisible tw:w-0 tw:opacity-0 tw:group-hover/sidebar:visible tw:group-hover/sidebar:w-auto tw:group-hover/sidebar:opacity-100 tw:group-has-[:focus-visible]/sidebar:visible tw:group-has-[:focus-visible]/sidebar:w-auto tw:group-has-[:focus-visible]/sidebar:opacity-100'
    : undefined

  // El diálogo nativo vuelve inerte el fondo y administra Tab/Escape/foco móvil.
  // Escritorio conserva el mismo store y los dos modos: oculto o riel de 4rem.
  useEffect(() => {
    const element = dialog.current
    if (!mobile || !element) return
    if (mobileOpen && !element.open) element.showModal()
    if (!mobileOpen && element.open) element.close()
  }, [mobile, mobileOpen])

  const content = <>
      <div className="tw:flex tw:h-16 tw:shrink-0 tw:items-center tw:justify-between tw:border-b tw:border-white/10 tw:px-4">
        <Link href="/" className="tw:inline-flex tw:min-w-0 tw:items-center tw:gap-3 tw:font-sans tw:text-xl tw:font-semibold tw:text-white tw:no-underline tw:focus-visible:outline-2 tw:focus-visible:outline-offset-2 tw:focus-visible:outline-white" aria-label="ECA-QMS, inicio" onClick={() => setMobileOpen(false)}>
          <span className="tw:inline-flex tw:size-8 tw:shrink-0 tw:items-center tw:justify-center tw:rounded-md tw:border-2 tw:border-current tw:text-[22px]" aria-hidden="true">E</span>
          <span className={cn('tw:whitespace-nowrap', labelClass)}>ECA QMS</span>
        </Link>
        {mobile && <Button variant="ghost" autoFocus aria-label="Cerrar menú" onClick={() => setMobileOpen(false)} className="tw:size-9 tw:min-h-9 tw:p-0 tw:text-white/70 tw:enabled:hover:bg-white/10 tw:enabled:hover:text-white tw:focus-visible:outline-white"><X className="tw:size-5" aria-hidden="true" /></Button>}
      </div>
      <nav id="sidebar-navigation" className="tw:min-h-0 tw:flex-1 tw:overflow-x-hidden tw:overflow-y-auto tw:overscroll-contain tw:py-2" aria-label="Módulos del sistema">
        {sections.map((section, index) => {
          const linksVisibles = section.links.filter((link) => tienePermiso(permisos, moduloDeRuta(link.href), false, user?.rol))
          if (linksVisibles.length === 0) return null
          const links = linksVisibles.map((link) => {
            const isActive = pathname === link.href || (link.href !== '/' && pathname.startsWith(link.href + '/'))
            const preload = () => { const cfg = prefetchMap[link.href]; if (cfg) prefetch(cfg) }
            const Icon = link.icon
            return <li key={link.href}><Link href={link.href} className={cn('tw:flex tw:min-h-11 tw:min-w-0 tw:items-center tw:gap-3 tw:px-4 tw:py-2 tw:text-base tw:leading-6 tw:no-underline tw:hover:bg-white/10 tw:hover:text-white tw:focus-visible:bg-white/10 tw:focus-visible:outline-2 tw:focus-visible:-outline-offset-2 tw:focus-visible:outline-white', isActive ? 'tw:bg-white/10 tw:font-medium tw:text-white' : 'tw:text-white/70', section.label && 'tw:pl-7')} title={link.label}
              aria-label={link.label} aria-current={isActive ? 'page' : undefined} onClick={() => setMobileOpen(false)} onMouseEnter={preload} onFocus={preload}>
              {section.label ? <span className="tw:size-1.5 tw:shrink-0 tw:rounded-full tw:bg-current" aria-hidden="true" /> : <Icon className="tw:size-6 tw:shrink-0" aria-hidden="true" />}<span className={cn('tw:min-w-0 tw:truncate', labelClass)}>{link.label}</span>
            </Link></li>
          })
          if (!section.label) return <div key="dashboard"><ul className="tw:m-0 tw:list-none tw:p-0">{links}</ul><p className={cn('tw:m-0 tw:px-4 tw:pb-2 tw:pt-5 tw:text-xs tw:font-semibold tw:uppercase tw:tracking-wide tw:text-white/50', labelClass)}>Módulos</p></div>
          const hasActiveLink = linksVisibles.some((link) => pathname === link.href || (link.href !== '/' && pathname.startsWith(link.href + '/')))
          const isOpen = expandedGroups[section.label] ?? hasActiveLink
          const Icon = section.links[0].icon
          return <div key={section.label}>
            <Button variant="ghost" onClick={() => setGroupOpen(section.label, !isOpen)} aria-label={section.label} aria-expanded={isOpen} aria-controls={`sidebar-group-${index}`} title={section.label} className="tw:min-h-11 tw:w-full tw:justify-start tw:gap-3 tw:rounded-none tw:border-0 tw:px-4 tw:py-2 tw:font-medium tw:text-white/80 tw:enabled:hover:bg-white/10 tw:enabled:hover:text-white tw:focus-visible:-outline-offset-2 tw:focus-visible:outline-white">
              <Icon className="tw:size-6 tw:shrink-0" aria-hidden="true" /><span className={cn('tw:min-w-0 tw:flex-1 tw:truncate tw:text-left', labelClass)}>{section.label}</span>
              <ChevronDown className={cn('tw:ml-auto tw:size-4 tw:shrink-0', isOpen && 'tw:rotate-180', labelClass)} aria-hidden="true" />
            </Button>
            <ul id={`sidebar-group-${index}`} hidden={!isOpen} className={cn('tw:m-0 tw:list-none tw:p-0', compact && isOpen && 'tw:hidden tw:group-hover/sidebar:block tw:group-has-[:focus-visible]/sidebar:block')}>{links}</ul>
          </div>
        })}
      </nav>
      {/* Mantener la flecha en el mismo punto del riel al hacer hover: no debe
          desplazarse justo cuando el usuario intenta pulsarla. */}
      {!mobile && <div className={cn('tw:flex tw:h-12 tw:shrink-0 tw:items-center tw:border-t tw:border-white/10 tw:px-3', compact ? 'tw:justify-start' : 'tw:justify-end')}>
        <Button variant="ghost" onClick={toggleCollapsed} aria-label={collapsed ? 'Expandir menú' : 'Contraer menú'} aria-expanded={!collapsed} aria-controls="sidebar-navigation" className="tw:size-9 tw:min-h-9 tw:p-0 tw:text-white/60 tw:enabled:hover:bg-white/10 tw:enabled:hover:text-white tw:focus-visible:outline-white">{collapsed ? <ChevronRight className="tw:size-5" aria-hidden="true" /> : <ChevronLeft className="tw:size-5" aria-hidden="true" />}</Button>
      </div>}
    </>

  if (mobile) return <dialog ref={dialog} id="app-sidebar" aria-label="Menú principal" onCancel={(event) => { event.preventDefault(); setMobileOpen(false) }} onClose={() => setMobileOpen(false)} onKeyDown={(event) => {
    if (event.key !== 'Tab') return
    // El fondo es inerte por showModal; envolver los extremos evita que Tab
    // abandone la navegación hacia el chrome del navegador en algunos motores.
    const items = Array.from(event.currentTarget.querySelectorAll<HTMLElement>('a[href], button:not(:disabled), [tabindex="0"]')).filter(element => element.getClientRects().length > 0)
    const first = items[0]
    const last = items.at(-1)
    if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus() }
    else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus() }
  }} onClick={(event) => {
    // Solo el backdrop: un clic/selección dentro del contenido no cierra el menú.
    if (event.target !== event.currentTarget) return
    const rect = event.currentTarget.getBoundingClientRect()
    if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) setMobileOpen(false)
  }} className="tw:fixed tw:inset-y-0 tw:left-0 tw:right-auto tw:m-0 tw:h-dvh tw:max-h-none tw:w-64 tw:max-w-[calc(100vw-3rem)] tw:flex-col tw:overflow-hidden tw:border-0 tw:bg-sidebar tw:p-0 tw:font-sans tw:text-white tw:shadow-md tw:backdrop:bg-black/40 tw:open:flex">{content}</dialog>

  return <aside id="app-sidebar" aria-label="Menú principal" className={cn('tw:group/sidebar tw:fixed tw:inset-y-0 tw:left-0 tw:z-40 tw:flex tw:flex-col tw:overflow-hidden tw:border-r tw:border-white/10 tw:bg-sidebar tw:font-sans tw:text-white tw:max-[992px]:hidden', hidden ? 'tw:hidden' : compact ? 'tw:w-16 tw:hover:w-64 tw:has-[:focus-visible]:w-64' : 'tw:w-64')}>{content}</aside>
}

export default memo(Sidebar)

