'use client'

import { CButton } from '@coreui/react'
import { PAGE_SIZE } from '@/lib/queries/pagination'

// Paginación minimalista: una sola fila con el conteo total a la izquierda y,
// a la derecha, los controles de retroceso/avance rodeando el texto de posición.
// Sin botones por número de página: limpio y rápido de renderizar.
export default function Pagination({ page, count, busy, onChange }: {
  page: number
  count: number
  busy?: boolean
  onChange: (page: number) => void
}) {
  const pages = Math.max(1, Math.ceil(count / PAGE_SIZE))
  const anchoTotal = pages - 1

  return (
    <div className="flex flex-wrap items-center justify-between gap-3">
      <span className="text-qms-muted text-sm">{count} resultados</span>
      {pages > 1 && (
        <div className="flex items-center gap-2">
          <CButton type="button" color="secondary" variant="ghost" className="rounded-md" disabled={busy || page <= 0} onClick={() => onChange(page - 1)} aria-label="Página anterior">Anterior</CButton>
          <span className="text-qms-muted text-sm whitespace-nowrap">Página {page + 1} de {pages}</span>
          <CButton type="button" color="secondary" variant="ghost" className="rounded-md" disabled={busy || page >= anchoTotal} onClick={() => onChange(page + 1)} aria-label="Página siguiente">Siguiente</CButton>
        </div>
      )}
    </div>
  )
}

