import type { ComponentPropsWithRef } from 'react'
import { cn } from './cn'

const variants = {
  primary: 'tw:border-primary/20 tw:bg-primary-subtle tw:text-primary',
  secondary: 'tw:border-border tw:bg-background tw:text-muted',
  danger: 'tw:border-red-200 tw:bg-red-50 tw:text-red-800',
  success: 'tw:border-green-200 tw:bg-green-50 tw:text-green-800',
  warning: 'tw:border-amber-200 tw:bg-amber-50 tw:text-amber-900',
  info: 'tw:border-blue-200 tw:bg-blue-50 tw:text-blue-800',
} as const

// Alias de los estados actuales; permiten migrar sin cambiar mapas de negocio.
const aliases = {
  red: 'danger', amber: 'warning', orange: 'warning', green: 'success',
  blue: 'info', purple: 'primary', gray: 'secondary',
} as const

export interface BadgeProps extends ComponentPropsWithRef<'span'> {
  variant?: keyof typeof variants | keyof typeof aliases | (string & {})
  size?: 'sm' | 'md'
}

export function Badge({ variant = 'secondary', size = 'md', className, ...props }: BadgeProps) {
  const resolved = Object.hasOwn(aliases, variant) ? aliases[variant as keyof typeof aliases] : Object.hasOwn(variants, variant) ? variant as keyof typeof variants : 'secondary'
  return <span {...props} className={cn(
    'tw:inline-flex tw:items-center tw:gap-1 tw:rounded-md tw:border tw:font-sans tw:font-medium tw:leading-5',
    size === 'sm' ? 'tw:px-1.5 tw:py-0.5 tw:text-xs' : 'tw:px-2 tw:py-0.5 tw:text-sm',
    variants[resolved], className,
  )} />
}

export default Badge

