components/ui/tailwind/Modal.tsx:
'use client'

import { useEffect, useId, useRef, type ReactNode } from 'react'
import { createPortal } from 'react-dom'
import { X } from 'lucide-react'
import Button from './Button'
import { cn } from './cn'

interface ModalProps { open: boolean; onClose: () => void; title: string; size?: 'sm' | 'md' | 'lg' | 'xl'; children: ReactNode }
const widths = { sm: 'tw:max-w-[300px]', md: 'tw:max-w-[500px]', lg: 'tw:max-w-[800px]', xl: 'tw:max-w-[1140px]' }

/** Solo presentación. El formulario conserva sus hooks/borrador fuera del portal.
 * showModal administra la pila nativa y vuelve inerte el fondo de cada diálogo. */
export default function Modal({ open, onClose, title, size = 'md', children }: ModalProps) {
  const id = useId()
  const dialog = useRef<HTMLDialogElement>(null)
  const backdropDown = useRef(false)
  useEffect(() => {
    const element = dialog.current
    if (!open || !element) return
    const origin = document.activeElement instanceof HTMLElement ? document.activeElement : null
    element.showModal()
    return () => {
      element.close()
      if (document.activeElement === document.body && origin?.isConnected) origin.focus()
    }
  }, [open])

  if (!open || typeof document === 'undefined') return null
  const outside = (event: React.MouseEvent<HTMLDialogElement>) => {
    if (event.target !== event.currentTarget) return false
    const rect = event.currentTarget.getBoundingClientRect()
    return event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom
  }
  return createPortal(<dialog ref={dialog} aria-labelledby={id} aria-modal="true" onCancel={(event) => {
    event.preventDefault()
    event.stopPropagation()
    onClose()
  }} onMouseDown={(event) => { backdropDown.current = outside(event) }} onClick={(event) => {
    if (backdropDown.current && outside(event)) onClose()
    backdropDown.current = false
  }} onKeyDown={(event) => {
    if (event.key !== 'Tab') return
    const items = Array.from(event.currentTarget.querySelectorAll<HTMLElement>('a[href], button:not(:disabled), input:not(:disabled), select:not(:disabled), textarea:not(:disabled), [tabindex="0"]')).filter(node => node.getClientRects().length > 0)
    const first = items[0], last = items.at(-1)
    if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus() }
    else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus() }
  }} className={cn('tw:fixed tw:inset-0 tw:m-auto tw:max-h-[calc(100dvh-2rem)] tw:w-[calc(100vw-2rem)] tw:flex-col tw:overflow-hidden tw:rounded-lg tw:border tw:border-border tw:bg-surface tw:p-0 tw:font-sans tw:text-foreground tw:shadow-md tw:backdrop:bg-black/50 tw:open:flex', widths[size])}>
    <div className="tw:flex tw:shrink-0 tw:items-center tw:justify-between tw:gap-3 tw:bg-sidebar tw:px-4 tw:py-3 tw:text-white">
      <h2 id={id} className="tw:m-0 tw:text-xl tw:font-medium tw:leading-7">{title}</h2>
      <Button variant="ghost" onClick={onClose} aria-label="Cerrar" className="tw:size-9 tw:min-h-9 tw:p-0 tw:text-white/80 tw:enabled:hover:bg-white/10 tw:enabled:hover:text-white tw:focus-visible:outline-white"><X className="tw:size-5" aria-hidden="true" /></Button>
    </div>
    <div className="tw:min-h-0 tw:overflow-y-auto tw:overscroll-contain tw:p-4">{children}</div>
  </dialog>, document.body)
}

