'use client'

import { CFormInput, CButton } from '@coreui/react'
import { useEffect, useRef, useState } from 'react'
import { RefreshCw, Eye, EyeOff, Copy, Check, X, KeyRound, Loader2 } from '@/components/ui/icons'
import Modal from '@/components/Modal'
import Button from '@/components/ui/Button'
import { showError, showSuccess } from '@/lib/services/errorToast'
import { generatePassword } from '@/lib/services/passwordGenerator'
import { mutateUsuario, type Usuario } from '@/lib/queries/useUsuarios'

interface ResetPasswordModalProps {
  open: boolean
  usuario: Usuario | null
  onClose: () => void
  onSaved: () => void
}

export default function ResetPasswordModal({ open, usuario, onClose, onSaved }: ResetPasswordModalProps) {
  const [password, setPassword] = useState('')
  const [show, setShow] = useState(false)
  const [saving, setSaving] = useState(false)
  const [copied, setCopied] = useState(false)
  const pending = useRef(false)
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  useEffect(() => () => { if (timeoutRef.current) clearTimeout(timeoutRef.current) }, [])

  function generar() {
    if (pending.current) return
    setPassword(generatePassword(16))
    setShow(true)
    setCopied(false)
  }

  function limpiar() {
    if (pending.current) return
    setPassword('')
    setShow(false)
    setCopied(false)
  }

  function copiar() {
    if (!password) return
    navigator.clipboard.writeText(password).then(
      () => {
        setCopied(true)
        showSuccess('Contraseña copiada')
        if (timeoutRef.current) clearTimeout(timeoutRef.current)
        timeoutRef.current = setTimeout(() => setCopied(false), 2000)
      },
      () => showError(null, 'No se pudo copiar la contraseña')
    )
  }

  async function guardar() {
    if (!usuario || !password || pending.current) return
    pending.current = true
    setSaving(true)
    try {
      await mutateUsuario('PATCH', { id: usuario.id, newPassword: password }, 'No se pudo restablecer la contraseña')
      showSuccess('Contraseña actualizada')
      setPassword('')
      setShow(false)
      setCopied(false)
      onClose()
      onSaved()
    } catch (error) {
      showError(error, 'No se pudo restablecer la contraseña')
    } finally {
      pending.current = false
      setSaving(false)
    }
  }

  function cerrar() {
    if (pending.current) return
    limpiar()
    onClose()
  }

  return (
    <Modal open={open} onClose={cerrar} title="Resetear contraseña" size="sm">
      <div className="space-y-4">
        <p className="m-0 text-sm text-gray-600">
          Genera una nueva contraseña para <span className="font-semibold text-qms-dark">{usuario?.nombre}</span>.
        </p>

        {password ? (
          <div className="space-y-3">
            <div className="flex items-center gap-2 rounded-card border border-gray-200 bg-qms-surface px-3 py-2 transition focus-within:border-qms-primary focus-within:ring-2 focus-within:ring-blue-100">
              <KeyRound className="h-4 w-4 shrink-0 text-qms-primary" />
              <CFormInput
                type={show ? 'text' : 'password'}
                readOnly
                value={password}
                className="min-w-0 flex-1 font-mono"
              />
              <CButton color="secondary" variant="outline" type="button" onClick={() => setShow(!show)} className="shrink-0 cursor-pointer transition-colors hover:opacity-70" title={show ? 'Ocultar' : 'Mostrar'}>
                {show ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
              </CButton>
              <CButton color="secondary" variant="outline" type="button" onClick={limpiar} disabled={saving} className="shrink-0 cursor-pointer transition-colors hover:opacity-70" title="Limpiar">
                <X className="h-4 w-4" />
              </CButton>
            </div>
            <div className="flex items-center justify-between">
              <Button type="button" size="sm" variant="secondary" onClick={generar} disabled={saving}>
                <RefreshCw className="h-3.5 w-3.5" /> Regenerar
              </Button>
              <div className="flex gap-2">
                <Button type="button" size="sm" variant="secondary" onClick={copiar}>
                  {copied ? <Check className="h-3.5 w-3.5" /> : <Copy className="h-3.5 w-3.5" />}
                  {copied ? 'Copiada' : 'Copiar'}
                </Button>
                <Button type="button" size="sm" onClick={guardar} disabled={saving}>
                  {saving ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <KeyRound className="h-3.5 w-3.5" />}
                  Guardar
                </Button>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex items-center justify-between rounded-card border border-dashed border-gray-300 bg-gray-50 px-3 py-3">
            <span className="text-sm text-qms-muted">No hay contraseña generada</span>
            <Button type="button" size="sm" onClick={generar}>
              <RefreshCw className="h-3.5 w-3.5" /> Generar
            </Button>
          </div>
        )}
      </div>
    </Modal>
  )
}

components/usuarios/UsuarioFormModal.tsx:
'use client'

import { CFormLabel, CFormInput } from '@coreui/react'
import { useRef, useState } from 'react'
import { Trash2 } from '@/components/ui/icons'
import Modal from '@/components/Modal'
import Button from '@/components/ui/Button'
import Select from '@/components/ui/Select'
import { showError, showSuccess } from '@/lib/services/errorToast'
import { generatePassword } from '@/lib/services/passwordGenerator'
import { mutateUsuario, type Usuario } from '@/lib/queries/useUsuarios'

interface UsuarioFormModalProps {
  open: boolean
  mode: 'crear' | 'editar'
  usuario?: Usuario | null
  esAuto?: boolean
  onClose: () => void
  onSuccess: (result: { tempPassword?: string }) => void
  onDelete: (usuario: Usuario) => Promise<void>
}

const inputClass =
  'w-full rounded-md border border-gray-200 bg-white px-3 py-2 text-sm text-gray-900 outline-none transition placeholder:text-gray-400 focus:border-blue-500 focus:ring-2 focus:ring-blue-100 dark:border-gray-600 dark:bg-gray-800 dark:text-white'
const labelClass = 'mb-1.5 block text-sm font-medium text-gray-700 dark:text-gray-300'

export default function UsuarioFormModal({ open, mode, usuario, esAuto, onClose, onSuccess, onDelete }: UsuarioFormModalProps) {
  const esEditar = mode === 'editar' && !!usuario
  const [saving, setSaving] = useState(false)
  const [confirmarEliminar, setConfirmarEliminar] = useState(false)
  const [eliminando, setEliminando] = useState(false)
  // El ref bloquea dos eventos en el mismo frame, antes del siguiente render.
  const pending = useRef(false)

  function cerrar() {
    if (pending.current) return
    setConfirmarEliminar(false)
    setEliminando(false)
    onClose()
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    if (pending.current) return
    pending.current = true
    setSaving(true)
    try {
      const form = new FormData(e.currentTarget as HTMLFormElement)
      const nombre = (form.get('nombre') as string).trim()
      const email = (form.get('email') as string).trim()
      // Los controles disabled no aparecen en FormData: omitirlos conserva el rol
      // y el estado al editar la propia cuenta, sin enviar null a la API.
      const access = esAuto ? {} : { rol: form.get('rol'), estado: form.get('estado') }

      if (esEditar && usuario) {
        await mutateUsuario('PATCH', { id: usuario.id, nombre, email, ...access }, 'No se pudo actualizar el usuario')
        showSuccess('Usuario actualizado')
        setConfirmarEliminar(false)
        onSuccess({})
        return
      }

      const password = generatePassword(16)
      await mutateUsuario('POST', { nombre, email, ...access, password }, 'No se pudo crear el usuario')
      showSuccess('Usuario creado')
      onSuccess({ tempPassword: password })
    } catch (error) {
      showError(error, 'No se pudo guardar el usuario')
    } finally {
      pending.current = false
      setSaving(false)
    }
  }

  async function handleEliminar() {
    if (!usuario || pending.current) return
    pending.current = true
    setEliminando(true)
    try {
      await onDelete(usuario)
      setConfirmarEliminar(false)
    } catch (error) {
      showError(error, 'No se pudo eliminar el usuario')
    } finally {
      pending.current = false
      setEliminando(false)
    }
  }

  return (
    <Modal open={open} onClose={cerrar} title={esEditar ? 'Editar usuario' : 'Nuevo usuario'} size="md">
      <form key={usuario?.id ?? 'crear'} onSubmit={handleSubmit} className="space-y-4">
        <div>
          <CFormLabel className={labelClass}>Nombre completo</CFormLabel>
          <CFormInput name="nombre" required disabled={saving || eliminando} defaultValue={usuario?.nombre} className={inputClass} placeholder="Ej: María Fernández" />
        </div>
        <div>
          <CFormLabel className={labelClass}>Correo electrónico</CFormLabel>
          <CFormInput name="email" type="email" required disabled={saving || eliminando} defaultValue={usuario?.email} className={inputClass} placeholder="usuario@eca-qms.com" />
        </div>
        <div className="grid grid-cols-2 gap-4">
          <div>
            <CFormLabel className={labelClass}>Rol</CFormLabel>
            <Select name="rol" required defaultValue={usuario?.rol || ''} disabled={esAuto || saving || eliminando} className="w-full">
              <option value="" disabled>Seleccionar rol</option>
              <option value="admin">Administrador</option>
              <option value="calidad">Calidad</option>
              <option value="colaborador">Colaborador</option>
            </Select>
          </div>
          <div>
            <CFormLabel className={labelClass}>Estado</CFormLabel>
            <Select name="estado" required defaultValue={usuario?.estado || 'activo'} disabled={esAuto || saving || eliminando} className="w-full">
              <option value="activo">Activo</option>
              <option value="inactivo">Inactivo</option>
            </Select>
          </div>
        </div>
        <div className="flex items-center justify-between gap-2 border-t border-gray-200 pt-4">
          <div>
            {esEditar && usuario && !esAuto && (
              confirmarEliminar ? (
                <div className="flex items-center gap-2">
                  <span className="text-sm font-medium text-qms-danger">¿Eliminar a {usuario.nombre}?</span>
                  <Button type="button" size="sm" variant="secondary" disabled={saving || eliminando} onClick={() => setConfirmarEliminar(false)}>Cancelar</Button>
                  <Button type="button" size="sm" variant="danger" onClick={handleEliminar} loading={eliminando} disabled={saving}>
                    <Trash2 className="h-3.5 w-3.5" /> Eliminar
                  </Button>
                </div>
              ) : (
                <Button type="button" size="sm" variant="danger" disabled={saving} onClick={() => setConfirmarEliminar(true)}>
                  <Trash2 className="h-3.5 w-3.5" /> Eliminar
                </Button>
              )
            )}
          </div>
          <div className="flex items-center gap-2">
            <Button type="button" variant="secondary" onClick={cerrar} disabled={saving || eliminando}>Cancelar</Button>
            <Button type="submit" loading={saving} disabled={eliminando}>{esEditar ? 'Guardar cambios' : 'Crear usuario'}</Button>
          </div>
        </div>
      </form>
    </Modal>
  )
}

