'use client'

import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { useEffect, useState } from 'react'
import { useAuthStore } from '@/lib/store/auth-store'
import { retryRead } from '@/lib/errors/userError'

export default function QueryProvider({ children }: { children: React.ReactNode }) {
  const scope = useAuthStore((state) =>
    `${state.user?.id ?? 'public'}:${state.user?.rol ?? ''}:${state.vistaActiva ?? ''}`,
  )
  return <ScopedQueryProvider key={scope}>{children}</ScopedQueryProvider>
}

function ScopedQueryProvider({ children }: { children: React.ReactNode }) {
  const [queryClient] = useState(
    () =>
      new QueryClient({
        defaultOptions: {
          queries: {
            staleTime: 5 * 60 * 1000,
            gcTime: 30 * 60 * 1000,
            retry: retryRead,
            refetchOnWindowFocus: false,
            refetchOnReconnect: false,
            // Reutilizar lo fresco; recuperar lo vencido o invalidado al volver.
            // false dejaría pendientes las invalidaciones recibidas al navegar.
            refetchOnMount: true,
          },
          mutations: {
            retry: 0,
          },
        },
      }),
  )

  useEffect(() => () => { queryClient.clear() }, [queryClient])

  return (
    <QueryClientProvider client={queryClient}>
      {children}
    </QueryClientProvider>
  )
}

